import React, { createContext, useContext, useEffect, useState, ReactNode } from 'react';
import AsyncStorage from '@react-native-async-storage/async-storage';
import { UserSubscription, SubscriptionPlan } from '../types';
import { useAuth } from './AuthContext';
import {
  getUserSubscription,
  upgradeToPremium,
  cancelSubscription,
  canAddMedicine,
  canUseAISearch,
  canUseBarcodeScanner,
  shouldShowAds,
  getRemainingDays,
  SUBSCRIPTION_PLANS,
  formatPrice,
  getYearlySavings,
} from '../services/subscriptionService';
import { createScopedLogger } from '../utils/logger';

const log = createScopedLogger('SubscriptionContext');

const BARCODE_SCAN_COUNT_KEY = 'barcode_scan_count';

interface SubscriptionContextType {
  subscription: UserSubscription;
  isLoading: boolean;
  isPremium: boolean;
  plan: SubscriptionPlan;
  
  // Actions
  refreshSubscription: () => Promise<void>;
  upgrade: (billingPeriod: 'monthly' | 'yearly', transactionId?: string) => Promise<void>;
  cancel: () => Promise<void>;
  
  // Checks
  canAddMedicine: (currentCount: number) => { allowed: boolean; reason?: string };
  canUseAISearch: (dailyCount: number) => { allowed: boolean; reason?: string };
  canUseBarcodeScanner: () => { allowed: boolean; reason?: string; remaining?: number };
  shouldShowAds: () => boolean;
  remainingDays: number | null;
  
  // Barkod tarama
  barcodeScanCount: number;
  remainingBarcodeScans: number;
  incrementBarcodeScanCount: () => Promise<void>;
  
  // Pricing
  monthlyPrice: string;
  yearlyPrice: string;
  yearlySavings: { amount: number; percentage: number };
}

const defaultSubscription: UserSubscription = {
  tier: 'free',
  isActive: true,
};

const SubscriptionContext = createContext<SubscriptionContextType>({
  subscription: defaultSubscription,
  isLoading: true,
  isPremium: false,
  plan: SUBSCRIPTION_PLANS.free,
  refreshSubscription: async () => {},
  upgrade: async () => {},
  cancel: async () => {},
  canAddMedicine: () => ({ allowed: true }),
  canUseAISearch: () => ({ allowed: true }),
  canUseBarcodeScanner: () => ({ allowed: true, remaining: 5 }),
  shouldShowAds: () => true,
  remainingDays: null,
  barcodeScanCount: 0,
  remainingBarcodeScans: 5,
  incrementBarcodeScanCount: async () => {},
  monthlyPrice: '₺49,99',
  yearlyPrice: '₺349,99',
  yearlySavings: { amount: 250, percentage: 42 },
});

export function SubscriptionProvider({ children }: { children: ReactNode }) {
  const { user, isAuthenticated } = useAuth();
  const [subscription, setSubscription] = useState<UserSubscription>(defaultSubscription);
  const [isLoading, setIsLoading] = useState(true);
  const [barcodeScanCount, setBarcodeScanCount] = useState(0);

  // Barkod tarama sayacını yükle
  const loadBarcodeScanCount = async () => {
    try {
      const countStr = await AsyncStorage.getItem(BARCODE_SCAN_COUNT_KEY);
      if (countStr) {
        setBarcodeScanCount(parseInt(countStr, 10));
      }
    } catch (error) {
      log.error('Barkod sayaci yukleme hatasi', error);
    }
  };

  // Barkod tarama sayacını artır
  const incrementBarcodeScanCount = async () => {
    try {
      const newCount = barcodeScanCount + 1;
      await AsyncStorage.setItem(BARCODE_SCAN_COUNT_KEY, newCount.toString());
      setBarcodeScanCount(newCount);
    } catch (error) {
      log.error('Barkod sayaci guncelleme hatasi', error);
    }
  };

  const refreshSubscription = async () => {
    if (!user?.uid) {
      setSubscription(defaultSubscription);
      setIsLoading(false);
      return;
    }

    try {
      setIsLoading(true);
      const sub = await getUserSubscription(user.uid);
      setSubscription(sub);
    } catch (error) {
      log.error('Abonelik yenileme hatasi', error);
      setSubscription(defaultSubscription);
    } finally {
      setIsLoading(false);
    }
  };

  useEffect(() => {
    loadBarcodeScanCount();
  }, []);

  useEffect(() => {
    if (isAuthenticated && user) {
      refreshSubscription();
    } else {
      setSubscription(defaultSubscription);
      setIsLoading(false);
    }
  }, [isAuthenticated, user?.uid]);

  const upgrade = async (billingPeriod: 'monthly' | 'yearly', transactionId?: string) => {
    if (!user?.uid) throw new Error('Kullanıcı girişi gerekli');
    
    await upgradeToPremium(user.uid, billingPeriod, transactionId);
    await refreshSubscription();
  };

  const cancel = async () => {
    if (!user?.uid) throw new Error('Kullanıcı girişi gerekli');
    
    await cancelSubscription(user.uid);
    await refreshSubscription();
  };

  const isPremium = subscription.tier === 'premium' && subscription.isActive;
  const plan = SUBSCRIPTION_PLANS[subscription.tier];
  const remainingDays = getRemainingDays(subscription);
  
  // Kalan barkod tarama hakkı
  const barcodeScanLimit = plan.limits.barcodeScanLimit;
  const remainingBarcodeScans = barcodeScanLimit === -1 ? -1 : Math.max(0, barcodeScanLimit - barcodeScanCount);

  const value: SubscriptionContextType = {
    subscription,
    isLoading,
    isPremium,
    plan,
    refreshSubscription,
    upgrade,
    cancel,
    canAddMedicine: (currentCount: number) => canAddMedicine(currentCount, subscription),
    canUseAISearch: (dailyCount: number) => canUseAISearch(dailyCount, subscription),
    canUseBarcodeScanner: () => canUseBarcodeScanner(subscription, barcodeScanCount),
    shouldShowAds: () => shouldShowAds(subscription),
    remainingDays,
    barcodeScanCount,
    remainingBarcodeScans,
    incrementBarcodeScanCount,
    monthlyPrice: formatPrice(SUBSCRIPTION_PLANS.premium.price.monthly),
    yearlyPrice: formatPrice(SUBSCRIPTION_PLANS.premium.price.yearly),
    yearlySavings: getYearlySavings(),
  };

  return (
    <SubscriptionContext.Provider value={value}>
      {children}
    </SubscriptionContext.Provider>
  );
}

export function useSubscription() {
  const context = useContext(SubscriptionContext);
  if (!context) {
    throw new Error('useSubscription must be used within SubscriptionProvider');
  }
  return context;
}

import { useState, useEffect, useCallback } from 'react';
import { Platform } from 'react-native';
import { useRoute, RouteProp } from '@react-navigation/native';
import { format } from 'date-fns';
import { DateTimePickerEvent } from '@react-native-community/datetimepicker';

import { useMedicineStore } from '../stores/medicineStore';
import { RootStackParamList, MedicineAutocompleteResult } from '../types';
import { calculateMedicineTimes } from '../utils/timeCalculator';
import { useTheme } from '../contexts/ThemeContext';
import { useLanguage } from '../contexts/LanguageContext';
import { autocomplete } from '../services/globalMedicineService';
import { useDebounce } from './useDebounce';
import { useMedicinePersistence } from './useMedicinePersistence';
import {
  AddMedicineFormState,
  AutocompleteState,
  TimePickerState,
  AddMedicineRouteParams,
  FREQUENCY_OPTIONS,
} from '../types/addMedicine.types';
import { createScopedLogger } from '../utils/logger';

const log = createScopedLogger('AddMedicine');

type RouteProps = RouteProp<RootStackParamList, 'AddMedicine'>;

export function useAddMedicine() {
  const route = useRoute<RouteProps>();
  const routeParams: AddMedicineRouteParams = route.params || {};

  const { colors, isDark } = useTheme();
  const { t, language } = useLanguage();
  const { getMedicineById, settings, getNextAvailableColor } = useMedicineStore();

  const existingMedicine = routeParams.medicineId
    ? getMedicineById(routeParams.medicineId)
    : undefined;
  const isEditing = !!existingMedicine;

  // Persistence hook
  const {
    handleScanBarcode,
    handleSave: persistSave,
    handleCancel,
    settings: persistSettings,
  } = useMedicinePersistence({
    isEditing,
    medicineId: routeParams.medicineId,
    t,
    language,
  });

  // Yeni ilaç için otomatik renk belirle
  const initialColor = existingMedicine?.color || getNextAvailableColor();

  // Form state
  const [formState, setFormState] = useState<AddMedicineFormState>({
    name: existingMedicine?.name || routeParams.prefillName || routeParams.scannedName || '',
    dosage:
      existingMedicine?.dosage || routeParams.prefillDosage || routeParams.scannedDosage || '',
    frequency: existingMedicine?.frequency || 3,
    instruction: existingMedicine?.instructions || 'any_time',
    selectedColor: initialColor,
    customTimes: existingMedicine?.customTimes || [],
    useCustomTimes: !!(existingMedicine?.customTimes && existingMedicine.customTimes.length > 0),
    // Stok takibi
    stockEnabled: existingMedicine?.stockEnabled ?? false,
    stockCount: existingMedicine?.stockCount ?? 30,
    stockThreshold: existingMedicine?.stockThreshold ?? 5,
    stockUnit: existingMedicine?.stockUnit ?? 'tablet',
    // Son kullanma tarihi
    expiryDate: existingMedicine?.expiryDate ?? null,
    expiryReminderDays: existingMedicine?.expiryReminderDays ?? 30,
  });

  // Autocomplete state
  const [autocompleteState, setAutocompleteState] = useState<AutocompleteState>({
    showAutocomplete: false,
    results: [],
    isLoading: false,
    inputFocused: false,
  });

  // TimePicker state
  const [timePickerState, setTimePickerState] = useState<TimePickerState>({
    showTimePicker: false,
    editingTimeIndex: null,
    tempTime: new Date(),
  });

  const debouncedName = useDebounce(formState.name, 300);

  // Prefill effect
  useEffect(() => {
    const updates: Partial<AddMedicineFormState> = {};
    if (routeParams.prefillName) updates.name = routeParams.prefillName;
    if (routeParams.prefillDosage) updates.dosage = routeParams.prefillDosage;
    if (routeParams.scannedName) updates.name = routeParams.scannedName;
    if (routeParams.scannedDosage) updates.dosage = routeParams.scannedDosage;

    if (Object.keys(updates).length > 0) {
      setFormState(prev => ({ ...prev, ...updates }));
    }
  }, [
    routeParams.prefillName,
    routeParams.prefillDosage,
    routeParams.scannedName,
    routeParams.scannedDosage,
  ]);

  // Autocomplete effect - race condition korumalı
  useEffect(() => {
    let cancelled = false;

    const searchAutocomplete = async () => {
      if (routeParams.prefillName || routeParams.scannedName) {
        setAutocompleteState(prev => ({ ...prev, showAutocomplete: false }));
        return;
      }

      if (debouncedName.length < 2 || !autocompleteState.inputFocused) {
        setAutocompleteState(prev => ({ ...prev, showAutocomplete: false, results: [] }));
        return;
      }

      setAutocompleteState(prev => ({ ...prev, isLoading: true }));
      try {
        const results = await autocomplete(debouncedName, 'TR', 5);

        // Eğer bu effect temizlenmişse (cancelled), state güncelleme
        if (cancelled) return;

        setAutocompleteState(prev => ({
          ...prev,
          results,
          showAutocomplete: results.length > 0,
          isLoading: false,
        }));
      } catch (error) {
        // Eğer cancelled ise log bile atma
        if (cancelled) return;

        log.error('Autocomplete hatasi', error);
        setAutocompleteState(prev => ({
          ...prev,
          results: [],
          showAutocomplete: false,
          isLoading: false,
        }));
      }
    };

    searchAutocomplete();

    // Cleanup: Yeni bir arama başladığında eskisini iptal et
    return () => {
      cancelled = true;
    };
  }, [
    debouncedName,
    autocompleteState.inputFocused,
    routeParams.prefillName,
    routeParams.scannedName,
  ]);

  // Preview times
  const previewTimes = calculateMedicineTimes('preview', {
    wakeUpTime: settings.wakeUpTime,
    sleepTime: settings.sleepTime,
    frequency: formState.frequency,
    instruction: formState.instruction,
  });

  // Form field updaters
  const updateFormField = useCallback(
    <K extends keyof AddMedicineFormState>(field: K, value: AddMedicineFormState[K]) => {
      setFormState(prev => ({ ...prev, [field]: value }));
    },
    []
  );

  const setNameInputFocused = useCallback((focused: boolean) => {
    setAutocompleteState(prev => ({ ...prev, inputFocused: focused }));
  }, []);

  const handleSelectAutocomplete = useCallback((item: MedicineAutocompleteResult) => {
    setFormState(prev => ({ ...prev, name: item.name, dosage: item.dosage }));
    setAutocompleteState(prev => ({ ...prev, showAutocomplete: false, inputFocused: false }));
  }, []);

  // Time management callbacks
  const handleAddTime = useCallback(() => {
    setTimePickerState({ showTimePicker: true, editingTimeIndex: null, tempTime: new Date() });
  }, []);

  const handleEditTime = useCallback((index: number, time: string) => {
    const [hours, minutes] = time.split(':').map(Number);
    const date = new Date();
    date.setHours(hours, minutes, 0, 0);
    setTimePickerState({ showTimePicker: true, editingTimeIndex: index, tempTime: date });
  }, []);

  const handleDeleteTime = useCallback((index: number) => {
    setFormState(prev => {
      const newTimes = prev.customTimes.filter((_, i) => i !== index);
      return { ...prev, customTimes: newTimes, useCustomTimes: newTimes.length > 0 };
    });
  }, []);

  const saveTimeSelection = useCallback(
    (date: Date) => {
      const timeStr = format(date, 'HH:mm');

      setFormState(prev => {
        let newTimes: string[];
        if (timePickerState.editingTimeIndex !== null) {
          newTimes = [...prev.customTimes];
          newTimes[timePickerState.editingTimeIndex] = timeStr;
        } else {
          if (prev.customTimes.includes(timeStr)) {
            return prev;
          }
          newTimes = [...prev.customTimes, timeStr];
        }
        return { ...prev, customTimes: newTimes.sort(), useCustomTimes: true };
      });
      setTimePickerState(prev => ({ ...prev, showTimePicker: false }));
    },
    [timePickerState.editingTimeIndex]
  );

  const handleTimeChange = useCallback(
    (event: DateTimePickerEvent, selectedDate?: Date) => {
      if (Platform.OS === 'android') {
        setTimePickerState(prev => ({ ...prev, showTimePicker: false }));
      }

      if (selectedDate) {
        setTimePickerState(prev => ({ ...prev, tempTime: selectedDate }));

        if (Platform.OS === 'android') {
          saveTimeSelection(selectedDate);
        }
      }
    },
    [saveTimeSelection]
  );

  const handleConfirmTime = useCallback(() => {
    saveTimeSelection(timePickerState.tempTime);
  }, [saveTimeSelection, timePickerState.tempTime]);

  const switchToManualTimes = useCallback(() => {
    if (!formState.useCustomTimes && previewTimes.length > 0) {
      setFormState(prev => ({
        ...prev,
        customTimes: previewTimes.map(t => t.time),
        useCustomTimes: true,
      }));
    }
  }, [formState.useCustomTimes, previewTimes]);

  const closeTimePicker = useCallback(() => {
    setTimePickerState(prev => ({ ...prev, showTimePicker: false }));
  }, []);

  // Save wrapper - error handling ile
  const handleSave = useCallback(async () => {
    try {
      await persistSave(formState);
    } catch (error) {
      log.error('Ilac kaydedilirken hata', error);
      // Hata fırlat ki caller (screen) handle edebilsin
      throw error;
    }
  }, [persistSave, formState]);

  return {
    routeParams,
    isEditing,
    colors,
    isDark,
    t,
    language,
    formState,
    updateFormField,
    autocompleteState,
    setNameInputFocused,
    handleSelectAutocomplete,
    timePickerState,
    handleAddTime,
    handleEditTime,
    handleDeleteTime,
    handleTimeChange,
    handleConfirmTime,
    switchToManualTimes,
    closeTimePicker,
    previewTimes,
    settings,
    handleScanBarcode,
    handleSave,
    handleCancel,
    FREQUENCY_OPTIONS,
  };
}

import { useCallback } from 'react';
import { useNavigation } from '@react-navigation/native';
import { NativeStackNavigationProp } from '@react-navigation/native-stack';

import { useMedicineStore } from '../stores/medicineStore';
import { RootStackParamList } from '../types';
import {
  scheduleMedicineNotification,
  scheduleExpiryReminder,
  cancelExpiryReminder,
} from '../utils/notifications';
import { useSubscription } from '../contexts/SubscriptionContext';
import { useAlert } from '../contexts/AlertContext';
import { AddMedicineFormState } from '../types/addMedicine.types';
import { TranslationKey } from '../contexts/LanguageContext';
import { createScopedLogger } from '../utils/logger';
import { checkMultipleInteractions, getSeverityIcon } from '../services/drugInteraction';
import { calculateMedicineTimes } from '../utils/timeCalculator';

const log = createScopedLogger('MedicinePersistence');

type NavigationProp = NativeStackNavigationProp<RootStackParamList>;

interface UseMedicinePersistenceProps {
  isEditing: boolean;
  medicineId?: string;
  t: (key: TranslationKey, params?: Record<string, string | number>) => string;
  language: 'tr' | 'en';
}

export function useMedicinePersistence({
  isEditing,
  medicineId,
  t,
  language,
}: UseMedicinePersistenceProps) {
  const navigation = useNavigation<NavigationProp>();
  const { showAlert, showError } = useAlert();
  const {
    addMedicine,
    updateMedicine,
    getMedicineById,
    settings,
    getReminderTimesForMedicine,
    medicines,
  } = useMedicineStore();
  const { canAddMedicine: checkCanAddMedicine, canUseBarcodeScanner } = useSubscription();

  // Saatleri çakışma aralığına göre kaydır
  const adjustTimesForConflicts = useCallback(
    (originalTimes: string[], conflictingTimes: Set<string>, intervalMinutes: number): string[] => {
      const adjustedTimes: string[] = [];
      const allOccupiedTimes = new Set(conflictingTimes);

      for (const time of originalTimes) {
        if (!allOccupiedTimes.has(time)) {
          adjustedTimes.push(time);
          allOccupiedTimes.add(time);
        } else {
          // Çakışma var, yeni saat bul
          const [hours, minutes] = time.split(':').map(Number);
          let newMinutes = minutes;
          let newHours = hours;
          let foundSlot = false;

          // Maksimum 6 kez dene (60 dakika ileriye kadar)
          for (let attempt = 0; attempt < 6; attempt++) {
            newMinutes += intervalMinutes;
            if (newMinutes >= 60) {
              newHours += Math.floor(newMinutes / 60);
              newMinutes = newMinutes % 60;
            }
            if (newHours >= 24) {
              newHours = newHours % 24;
            }

            const candidateTime = `${newHours.toString().padStart(2, '0')}:${newMinutes.toString().padStart(2, '0')}`;

            if (!allOccupiedTimes.has(candidateTime)) {
              adjustedTimes.push(candidateTime);
              allOccupiedTimes.add(candidateTime);
              foundSlot = true;
              break;
            }
          }

          // Eğer uygun slot bulunamazsa orijinal zamanı kullan
          if (!foundSlot) {
            adjustedTimes.push(time);
          }
        }
      }

      return adjustedTimes.sort();
    },
    []
  );

  // Saat çakışma kontrolü
  // Döndürülen değer: { proceed: boolean, adjustedTimes?: string[] }
  // proceed: true ise devam et, false ise iptal
  // adjustedTimes: Otomatik düzenleme seçildiyse yeni saatler
  const checkTimeConflict = useCallback(
    async (
      formState: AddMedicineFormState
    ): Promise<{ proceed: boolean; adjustedTimes?: string[] }> => {
      // Yeni ilacın saatlerini belirle
      let newMedicineTimes: string[];

      if (formState.useCustomTimes && formState.customTimes.length > 0) {
        newMedicineTimes = formState.customTimes;
      } else {
        // Saatleri hesapla
        const calculatedTimes = calculateMedicineTimes('temp', {
          wakeUpTime: settings.wakeUpTime,
          sleepTime: settings.sleepTime,
          frequency: formState.frequency,
          instruction: formState.instruction,
        });
        newMedicineTimes = calculatedTimes.map(rt => rt.time);
      }

      // Mevcut aktif ilaçların tüm saatlerini topla
      const existingOccupiedTimes = new Set<string>();
      const existingConflicts: { medicineName: string; time: string }[] = [];

      for (const medicine of medicines) {
        if (!medicine.isActive) continue;
        if (isEditing && medicine.id === medicineId) continue;

        const medicineReminderTimes = getReminderTimesForMedicine(medicine.id);

        for (const rt of medicineReminderTimes) {
          existingOccupiedTimes.add(rt.time);
          if (newMedicineTimes.includes(rt.time)) {
            existingConflicts.push({
              medicineName: medicine.name,
              time: rt.time,
            });
          }
        }
      }

      if (existingConflicts.length === 0) {
        return { proceed: true };
      }

      // Çakışan saatleri grupla
      const conflictMessages = existingConflicts
        .map(c => `⏰ ${c.time} - ${c.medicineName}`)
        .join('\n');

      // Otomatik düzenleme için yeni saatleri hesapla
      const intervalMinutes = settings.conflictIntervalMinutes || 10;
      const adjustedTimes = adjustTimesForConflicts(
        newMedicineTimes,
        existingOccupiedTimes,
        intervalMinutes
      );

      // Düzenlenen saatleri göster
      const adjustedTimesPreview = adjustedTimes.join(', ');

      return new Promise<{ proceed: boolean; adjustedTimes?: string[] }>(resolve => {
        showAlert({
          type: 'warning',
          title:
            language === 'tr' ? '⏰ Saat Çakışması Tespit Edildi' : '⏰ Time Conflict Detected',
          message: `${language === 'tr' ? 'Bu ilaç aşağıdaki ilaçlarla aynı saate denk geliyor:' : 'This medicine conflicts with the following medicines:'}\n\n${conflictMessages}\n\n${language === 'tr' ? `Otomatik düzenleme: ${adjustedTimesPreview}` : `Auto-adjusted times: ${adjustedTimesPreview}`}`,
          buttons: [
            {
              text: t('cancel'),
              style: 'cancel',
              onPress: () => resolve({ proceed: false }),
            },
            {
              text: language === 'tr' ? 'Otomatik Düzenle' : 'Auto Adjust',
              style: 'default',
              onPress: () => {
                // Ayarlanan saatlerle devam et
                resolve({ proceed: true, adjustedTimes });
              },
            },
            {
              text: language === 'tr' ? 'Yine de Ekle' : 'Add Anyway',
              style: 'destructive',
              onPress: () => resolve({ proceed: true }),
            },
          ],
        });
      });
    },
    [
      medicines,
      settings,
      isEditing,
      medicineId,
      language,
      t,
      getReminderTimesForMedicine,
      adjustTimesForConflicts,
      showAlert,
    ]
  );

  const handleScanBarcode = useCallback(() => {
    const { allowed, reason, remaining } = canUseBarcodeScanner();

    if (!allowed) {
      showAlert({
        type: 'warning',
        title: language === 'tr' ? 'Barkod Tarama Hakkı Doldu' : 'Barcode Scan Limit Reached',
        message: reason,
        buttons: [
          { text: language === 'tr' ? 'İptal' : 'Cancel', style: 'cancel' },
          {
            text: language === 'tr' ? "Premium'a Geç" : 'Go Premium',
            style: 'default',
            onPress: () => navigation.navigate('Premium'),
          },
        ],
      });
      return;
    }

    if (remaining !== undefined && remaining !== -1 && remaining > 0) {
      showAlert({
        type: 'info',
        title: language === 'tr' ? 'Barkod Tarama' : 'Barcode Scan',
        message:
          language === 'tr'
            ? `Kalan tarama hakkınız: ${remaining}\n\nDevam etmek istiyor musunuz?`
            : `Remaining scans: ${remaining}\n\nDo you want to continue?`,
        buttons: [
          { text: language === 'tr' ? 'İptal' : 'Cancel', style: 'cancel' },
          {
            text: language === 'tr' ? 'Tara' : 'Scan',
            style: 'default',
            onPress: () => navigation.navigate('BarcodeScanner'),
          },
        ],
      });
      return;
    }

    navigation.navigate('BarcodeScanner');
  }, [canUseBarcodeScanner, language, navigation, showAlert]);

  const saveMedicine = useCallback(
    async (formState: AddMedicineFormState): Promise<boolean> => {
      try {
        const medicineData = {
          name: formState.name.trim(),
          dosage: formState.dosage.trim(),
          frequency: formState.useCustomTimes ? formState.customTimes.length : formState.frequency,
          instructions: formState.instruction,
          color: formState.selectedColor,
          customTimes: formState.useCustomTimes ? formState.customTimes : undefined,
          // Stok takibi
          stockEnabled: formState.stockEnabled,
          stockCount: formState.stockEnabled ? formState.stockCount : undefined,
          stockThreshold: formState.stockEnabled ? formState.stockThreshold : undefined,
          stockUnit: formState.stockEnabled ? formState.stockUnit : undefined,
          // Son kullanma tarihi
          expiryDate: formState.expiryDate || undefined,
          expiryReminderDays: formState.expiryDate ? formState.expiryReminderDays : undefined,
        };

        // Önce navigation'ı yap - async işlemler uzun sürerse kullanıcı beklemez
        navigation.goBack();

        if (isEditing && medicineId) {
          log.debug('Düzenleme modu - medicineData', {
            medicineId,
            customTimes: medicineData.customTimes,
            useCustomTimes: formState.useCustomTimes,
            frequency: medicineData.frequency,
          });

          updateMedicine(medicineId, medicineData);

          // State güncellenmesini bekle
          await new Promise(resolve => setTimeout(resolve, 50));

          const freshState = useMedicineStore.getState();
          const times = freshState.getReminderTimesForMedicine(medicineId);
          const medicine = freshState.getMedicineById(medicineId);

          log.debug('Düzenleme sonrası state', {
            timesCount: times.length,
            times: times.map(t => t.time),
            medicineCustomTimes: medicine?.customTimes,
          });

          if (medicine) {
            for (const time of times) {
              log.debug('Bildirim planlanıyor', { time: time.time });
              // Düzenleme modunda bypassBuffer=true - kullanıcı saati bilinçli değiştirdi
              await scheduleMedicineNotification(
                medicine,
                time,
                settings.fullScreenAlarmEnabled,
                true
              );
            }
            // Son kullanma tarihi bildirimi planla/iptal et
            if (formState.expiryDate && formState.expiryReminderDays) {
              await scheduleExpiryReminder(
                medicine,
                formState.expiryDate,
                formState.expiryReminderDays,
                language
              );
            } else {
              await cancelExpiryReminder(medicineId);
            }
          }
        } else {
          const newMedicineId = addMedicine({
            ...medicineData,
            startDate: new Date().toISOString(),
          });
          // CRITICAL: useMedicineStore.getState() kullan - hook closure'u eski state'e bakar
          // addMedicine senkron olsa da, hook'taki fonksiyonlar eski closure'da kalır
          const freshState = useMedicineStore.getState();
          const times = freshState.getReminderTimesForMedicine(newMedicineId);
          const medicine = freshState.getMedicineById(newMedicineId);

          log.debug('Yeni ilaç eklendi', {
            medicineId: newMedicineId,
            medicineName: medicine?.name,
            reminderTimesCount: times.length,
          });

          if (medicine && times.length > 0) {
            const now = new Date();
            log.debug('ALARM PLANLAMA BASLIYOR', {
              currentTime: now.toISOString(),
              currentHours: now.getHours(),
              currentMinutes: now.getMinutes(),
              timesToSchedule: times.map(t => t.time),
            });

            for (const time of times) {
              log.debug('Tekli alarm planlaniyor', { time: time.time });

              const result = await scheduleMedicineNotification(
                medicine,
                time,
                settings.fullScreenAlarmEnabled,
                true // bypassBuffer=true - kullanıcı bilinçli ekledi
              );

              log.debug('Alarm planlama sonucu', {
                time: time.time,
                result: result ? 'basarili' : 'basarisiz/null',
                resultId: result,
              });
            }
            // Son kullanma tarihi bildirimi planla
            if (formState.expiryDate && formState.expiryReminderDays) {
              await scheduleExpiryReminder(
                medicine,
                formState.expiryDate,
                formState.expiryReminderDays,
                language
              );
            }
          } else {
            log.warn('İlaç veya hatırlatma saatleri bulunamadı', {
              hasMedicine: !!medicine,
              timesCount: times.length,
            });
          }
        }

        return true;
      } catch (error) {
        const errorMessage = error instanceof Error ? error.message : String(error);
        log.error('Medicine save error', error);
        showError(t('error'), `${t('error_unknown')}\n\n${errorMessage}`);
        return false;
      }
    },
    [
      isEditing,
      medicineId,
      language,
      t,
      navigation,
      updateMedicine,
      addMedicine,
      settings.fullScreenAlarmEnabled,
      showError,
    ]
  );

  const handleSave = useCallback(
    async (formState: AddMedicineFormState) => {
      if (!formState.name.trim()) {
        showError(t('error'), t('error_required_field'));
        return false;
      }
      if (!formState.dosage.trim()) {
        showError(t('error'), t('error_required_field'));
        return false;
      }

      if (!isEditing) {
        const activeMedicines = medicines.filter(m => m.isActive);
        const limitCheck = checkCanAddMedicine(activeMedicines.length);
        if (!limitCheck.allowed) {
          showAlert({
            type: 'warning',
            title: language === 'tr' ? 'İlaç Limiti' : 'Medicine Limit',
            message:
              limitCheck.reason ||
              (language === 'tr'
                ? 'Ücretsiz planda en fazla 3 ilaç ekleyebilirsiniz.'
                : 'You can add up to 3 medicines in the free plan.'),
            buttons: [
              { text: t('cancel'), style: 'cancel' },
              {
                text: language === 'tr' ? "Premium'a Geç" : 'Go Premium',
                style: 'default',
                onPress: () => navigation.navigate('Premium'),
              },
            ],
          });
          return false;
        }
      }

      // İlaç etkileşim kontrolü
      const activeMedicineNames = medicines
        .filter(m => m.isActive && (!isEditing || m.id !== medicineId))
        .map(m => m.name);
      const allDrugNames = [...activeMedicineNames, formState.name.trim()];

      const interactionResult = checkMultipleInteractions(allDrugNames);

      if (interactionResult.hasInteractions) {
        const interactionMessages = interactionResult.interactions
          .map(i => `${getSeverityIcon(i.severity)} ${i.drug1} + ${i.drug2}\n${i.description}`)
          .join('\n\n');

        return new Promise<boolean>(resolve => {
          showAlert({
            type: 'warning',
            title:
              language === 'tr'
                ? '⚠️ İlaç Etkileşimi Tespit Edildi'
                : '⚠️ Drug Interaction Detected',
            message: `${interactionMessages}\n\n${language === 'tr' ? 'Yine de eklemek istiyor musunuz?' : 'Do you still want to add this medicine?'}`,
            buttons: [
              {
                text: t('cancel'),
                style: 'cancel',
                onPress: () => resolve(false),
              },
              {
                text: language === 'tr' ? 'Yine de Ekle' : 'Add Anyway',
                style: 'destructive',
                onPress: async () => {
                  // İlaç etkileşimi kabul edildi, şimdi saat çakışmasını kontrol et
                  const timeConflictResult = await checkTimeConflict(formState);
                  if (!timeConflictResult.proceed) {
                    resolve(false);
                    return;
                  }
                  // Otomatik düzenleme yapıldıysa güncellenmiş formState ile kaydet
                  const finalFormState = timeConflictResult.adjustedTimes
                    ? {
                        ...formState,
                        customTimes: timeConflictResult.adjustedTimes,
                        useCustomTimes: true,
                      }
                    : formState;
                  const result = await saveMedicine(finalFormState);
                  resolve(result);
                },
              },
            ],
          });
        });
      }

      // Saat çakışma kontrolü
      const timeConflictResult = await checkTimeConflict(formState);
      if (!timeConflictResult.proceed) {
        return false;
      }

      // Otomatik düzenleme yapıldıysa güncellenmiş formState ile kaydet
      const finalFormState = timeConflictResult.adjustedTimes
        ? {
            ...formState,
            customTimes: timeConflictResult.adjustedTimes,
            useCustomTimes: true,
          }
        : formState;

      return saveMedicine(finalFormState);
    },
    [
      isEditing,
      medicineId,
      medicines,
      checkCanAddMedicine,
      language,
      t,
      navigation,
      checkTimeConflict,
      saveMedicine,
      showAlert,
      showError,
    ]
  );

  const handleCancel = useCallback(() => {
    navigation.goBack();
  }, [navigation]);

  return {
    handleScanBarcode,
    handleSave,
    handleCancel,
    settings,
  };
}

import { useState, useCallback } from 'react';
import { Platform, Linking } from 'react-native';
import { useNavigation } from '@react-navigation/native';
import { NativeStackNavigationProp } from '@react-navigation/native-stack';
import { format } from 'date-fns';
import { DateTimePickerEvent } from '@react-native-community/datetimepicker';
import { useMedicineStore } from '../stores/medicineStore';
import { RootStackParamList } from '../types';
import notifee from '@notifee/react-native';
import {
  sendTestNotification,
  requestNotificationPermissions,
  scheduleTestAlarmNotification,
  scheduleMedicineNotification,
} from '../utils/notifications';
import { checkMultipleInteractions, getSeverityIcon } from '../services/drugInteraction';
import { useAlert } from '../contexts/AlertContext';

// Test ilaç verileri
const TEST_MEDICINE_NAMES = [
  'Aspirin',
  'Parol',
  'Majezik',
  'Arveles',
  'Nurofen',
  'Tylol',
  'Voltaren',
  'Cataflam',
  'Apranax',
  'Dikloron',
  'Aferin',
  'Gripin',
  'Minoset',
  'Vermidon',
  'Dolorex',
];

const TEST_MEDICINE_DOSES = [
  '500mg',
  '200mg',
  '100mg',
  '250mg',
  '400mg',
  '1 tablet',
  '2 tablet',
  '1 kapsu00fcl',
  '5ml',
  '10ml',
];

const TEST_INSTRUCTIONS = [
  'after_meal',
  'before_meal',
  'with_meal',
  'any_time',
  'empty_stomach',
  'before_sleep',
] as const;
import { speak } from '../utils/speech';
import { useTheme, ThemeMode } from '../contexts/ThemeContext';
import { useLanguage, Language } from '../contexts/LanguageContext';
import { useAuth } from '../contexts/AuthContext';
import { useSubscription } from '../contexts/SubscriptionContext';
import { createScopedLogger } from '../utils/logger';
import { CHANNELS } from '../constants';

const log = createScopedLogger('SettingsScreen');

type SettingsNavigationProp = NativeStackNavigationProp<RootStackParamList>;

export function useSettingsScreen() {
  const navigation = useNavigation<SettingsNavigationProp>();
  const { colors, isDark, theme, setTheme } = useTheme();
  const { language, setLanguage, t } = useLanguage();
  const { showAlert, showSuccess, showError, showInfo, showConfirm, showWarning } = useAlert();
  const {
    settings,
    updateSettings,
    syncToCloud,
    isSyncing,
    lastSyncAt,
    addMedicine,
    deleteMedicine,
    medicines,
    reminderTimes,
  } = useMedicineStore();
  const { user, logout } = useAuth();
  const { isPremium, remainingDays } = useSubscription();

  const [pickerState, setPickerState] = useState({
    showWakeUpPicker: false,
    showSleepPicker: false,
    showThemePicker: false,
    showLanguagePicker: false,
    showSnoozePicker: false,
    showSnoozeCountPicker: false,
    showVolumePicker: false,
    showQuietStartPicker: false,
    showQuietEndPicker: false,
    showConflictIntervalPicker: false,
  });

  const togglePicker = useCallback((pickerName: keyof typeof pickerState) => {
    setPickerState(prev => ({
      ...prev,
      [pickerName]: !prev[pickerName],
    }));
  }, []);

  const closePicker = useCallback((pickerName: keyof typeof pickerState) => {
    setPickerState(prev => ({
      ...prev,
      [pickerName]: false,
    }));
  }, []);

  const parseTimeToDate = useCallback((timeStr: string) => {
    const [hours, minutes] = timeStr.split(':').map(Number);
    const date = new Date();
    date.setHours(hours, minutes, 0, 0);
    return date;
  }, []);

  const handleTimeChange = useCallback(
    (settingKey: 'wakeUpTime' | 'sleepTime' | 'quietHoursStart' | 'quietHoursEnd') =>
      (event: DateTimePickerEvent, selectedDate?: Date) => {
        const pickerMap: Record<string, keyof typeof pickerState> = {
          wakeUpTime: 'showWakeUpPicker',
          sleepTime: 'showSleepPicker',
          quietHoursStart: 'showQuietStartPicker',
          quietHoursEnd: 'showQuietEndPicker',
        };

        if (Platform.OS !== 'ios') {
          closePicker(pickerMap[settingKey]);
        }

        if (selectedDate) {
          const timeStr = format(selectedDate, 'HH:mm');
          updateSettings({ [settingKey]: timeStr });
        }
      },
    [closePicker, updateSettings]
  );

  const handleTestNotification = useCallback(async () => {
    log.debug('handleTestNotification called');
    try {
      const hasPermission = await requestNotificationPermissions();
      log.debug('Permission result', { hasPermission });
      if (hasPermission) {
        await sendTestNotification();
        log.debug('sendTestNotification completed');
        showSuccess(
          t('success'),
          language === 'tr' ? 'Test bildirimi gönderildi!' : 'Test notification sent!'
        );
      } else {
        showAlert({
          type: 'warning',
          title: t('settings_notification_permission'),
          message:
            language === 'tr'
              ? 'Bildirimlerin çalışması için izin vermeniz gerekiyor.'
              : 'You need to grant permission for notifications to work.',
          buttons: [
            { text: t('cancel'), style: 'cancel' },
            { text: t('settings_open_settings'), onPress: () => Linking.openSettings() },
          ],
        });
      }
    } catch (error) {
      log.error('handleTestNotification error', error);
      showError(t('error'), String(error));
    }
  }, [language, t, showSuccess, showAlert, showError]);

  const handleTestVoice = useCallback(async () => {
    const message =
      language === 'tr'
        ? 'İlaç zamanı! Aspirin, 500 miligram. Yemekten sonra alınız.'
        : 'Medicine time! Aspirin, 500 milligrams. Take after meal.';
    await speak(message, language);
  }, [language]);

  const handleTestFullScreenAlarm = useCallback(() => {
    showConfirm(
      language === 'tr' ? 'Tam Ekran Alarm Testi' : 'Full Screen Alarm Test',
      language === 'tr'
        ? '2 saniye sonra tam ekran alarm açılacak.'
        : 'Full screen alarm will open in 2 seconds.',
      () => {
        setTimeout(() => {
          navigation.navigate('Alarm', {
            medicineId: 'test-medicine',
            reminderTimeId: 'test-reminder',
            scheduledTime: new Date().toISOString(),
          });
        }, 2000);
      },
      { confirmText: language === 'tr' ? 'Başlat' : 'Start', cancelText: t('cancel') }
    );
  }, [language, navigation, t, showConfirm]);

  const handleScheduleTestAlarm = useCallback(
    async (minutes: number) => {
      const hasPermission = await requestNotificationPermissions();
      if (!hasPermission) {
        showAlert({
          type: 'warning',
          title: t('settings_notification_permission'),
          message:
            language === 'tr'
              ? 'Bildirimlerin çalışması için izin vermeniz gerekiyor.'
              : 'You need to grant permission for notifications to work.',
          buttons: [
            { text: t('cancel'), style: 'cancel' },
            { text: t('settings_open_settings'), onPress: () => Linking.openSettings() },
          ],
        });
        return;
      }

      try {
        await scheduleTestAlarmNotification(minutes, language);
        const scheduledTime = new Date(Date.now() + minutes * 60 * 1000);
        const timeStr = format(scheduledTime, 'HH:mm:ss');

        // Saniye veya dakika olarak göster
        const seconds = Math.round(minutes * 60);
        const timeDisplay =
          seconds < 60
            ? language === 'tr'
              ? `${seconds} saniye`
              : `${seconds} seconds`
            : language === 'tr'
              ? `${minutes} dakika`
              : `${minutes} minutes`;

        showSuccess(
          language === 'tr' ? 'Alarm Planlandı' : 'Alarm Scheduled',
          language === 'tr'
            ? `Test alarmı saat ${timeStr} (${timeDisplay} sonra) çalacak.\n\nTelefonu sessiz moda alarak test edebilirsiniz.`
            : `Test alarm will ring at ${timeStr} (in ${timeDisplay}).\n\nYou can test by putting your phone in silent mode.`
        );
      } catch (error: unknown) {
        log.error('Test alarm planlama hatası', error);
        const errorObj = error as { message?: string };
        const errorMessage = errorObj?.message || String(error) || 'Bilinmeyen hata';
        showError(
          t('error'),
          language === 'tr'
            ? `Alarm planlanamadı.\n\nHata: ${errorMessage}`
            : `Failed to schedule alarm.\n\nError: ${errorMessage}`
        );
      }
    },
    [language, t, showAlert, showSuccess, showError]
  );

  const handleSync = useCallback(async () => {
    try {
      await syncToCloud();
      showSuccess(
        t('success'),
        language === 'tr'
          ? 'Verileriniz buluta yedeklendi.'
          : 'Your data has been backed up to cloud.'
      );
    } catch (error: unknown) {
      const errorMessage =
        error instanceof Error
          ? error.message
          : language === 'tr'
            ? 'Senkronizasyon başarısız oldu.'
            : 'Sync failed.';
      showError(t('error'), errorMessage);
    }
  }, [language, syncToCloud, t, showSuccess, showError]);

  // Test ilacı ekle (1 dakika sonraya alarm)
  const handleAddTestMedicine = useCallback(async () => {
    // Random seçimler
    const randomName = TEST_MEDICINE_NAMES[Math.floor(Math.random() * TEST_MEDICINE_NAMES.length)];
    const randomDose = TEST_MEDICINE_DOSES[Math.floor(Math.random() * TEST_MEDICINE_DOSES.length)];
    const randomInstruction =
      TEST_INSTRUCTIONS[Math.floor(Math.random() * TEST_INSTRUCTIONS.length)];
    const randomColor = `#${Math.floor(Math.random() * 16777215)
      .toString(16)
      .padStart(6, '0')}`;

    // 1 dakika sonrası için saat hesapla
    const alarmTime = new Date(Date.now() + 60 * 1000);
    const timeStr = format(alarmTime, 'HH:mm');

    const testMedicineName = `TEST-${randomName}`;

    // İlaç etkileşim kontrolü
    const activeMedicineNames = medicines.filter(m => m.isActive).map(m => m.name);
    const allDrugNames = [...activeMedicineNames, testMedicineName];

    const interactionResult = checkMultipleInteractions(allDrugNames);

    // Belirli bir saat icin cakisma kontrolu
    const checkTimeConflictForTime = (
      targetTime: string
    ): { medicineName: string; time: string }[] => {
      const conflicts: { medicineName: string; time: string }[] = [];

      for (const medicine of medicines) {
        if (!medicine.isActive) continue;

        const medicineReminderTimes = reminderTimes.filter(rt => rt.medicineId === medicine.id);

        for (const rt of medicineReminderTimes) {
          if (rt.time === targetTime) {
            conflicts.push({
              medicineName: medicine.name,
              time: rt.time,
            });
          }
        }
      }

      return conflicts;
    };

    // Saat cakismasi kontrolu - tum cakisan saatleri bulur
    const checkTimeConflict = (): { hasConflict: boolean; conflictMessages: string } => {
      const existingConflicts = checkTimeConflictForTime(timeStr);

      if (existingConflicts.length === 0) {
        return { hasConflict: false, conflictMessages: '' };
      }

      const messages = existingConflicts.map(c => `⏰ ${c.time} - ${c.medicineName}`).join('\n');

      return { hasConflict: true, conflictMessages: messages };
    };

    // Cakismayan ilk saati bul (maksimum 5 dakika ileriye kadar)
    const findNonConflictingTime = (
      baseTime: string
    ): { time: string; offsetMinutes: number } | null => {
      const [hours, mins] = baseTime.split(':').map(Number);
      const baseDate = new Date();
      baseDate.setHours(hours, mins, 0, 0);

      // Maksimum 5 dakika ileriye kadar dene
      for (let offset = 1; offset <= 5; offset++) {
        const candidateDate = new Date(baseDate.getTime() + offset * 60 * 1000);
        const candidateTime = format(candidateDate, 'HH:mm');
        const conflicts = checkTimeConflictForTime(candidateTime);

        if (conflicts.length === 0) {
          return { time: candidateTime, offsetMinutes: offset };
        }
      }

      // 5 dakika icinde cakismayan saat bulunamadi
      return null;
    };

    const doAddMedicine = async () => {
      // Test ilacı ekle
      const medicineId = addMedicine({
        name: testMedicineName,
        dosage: randomDose,
        frequency: 1,
        instructions: randomInstruction,
        color: randomColor,
        customTimes: [timeStr],
        startDate: new Date().toISOString(),
      });

      // Bildirim izni ve planlama
      const hasPermission = await requestNotificationPermissions();
      if (hasPermission) {
        // ReminderTime'ı bul ve bildirim planla
        const newReminderTimes = useMedicineStore.getState().reminderTimes;
        const reminderTime = newReminderTimes.find(rt => rt.medicineId === medicineId);
        const medicine = useMedicineStore.getState().getMedicineById(medicineId);

        if (reminderTime && medicine) {
          await scheduleMedicineNotification(medicine, reminderTime, true, true);
        }
      }

      showSuccess(
        language === 'tr' ? 'Test İlacı Eklendi' : 'Test Medicine Added',
        language === 'tr'
          ? `${randomName} (${randomDose}) eklendi.\n\nAlarm: ${timeStr} (1 dakika sonra)`
          : `${randomName} (${randomDose}) added.\n\nAlarm: ${timeStr} (in 1 minute)`
      );
    };

    // 1 dakika sonraya ekle fonksiyonu
    const doAddMedicineWithOffset = async (offsetMinutes: number) => {
      const newAlarmTime = new Date(Date.now() + (60 + offsetMinutes * 60) * 1000);
      const newTimeStr = format(newAlarmTime, 'HH:mm');

      const medicineId = addMedicine({
        name: testMedicineName,
        dosage: randomDose,
        frequency: 1,
        instructions: randomInstruction,
        color: randomColor,
        customTimes: [newTimeStr],
        startDate: new Date().toISOString(),
      });

      const hasPermission = await requestNotificationPermissions();
      if (hasPermission) {
        const newReminderTimes = useMedicineStore.getState().reminderTimes;
        const reminderTime = newReminderTimes.find(rt => rt.medicineId === medicineId);
        const medicine = useMedicineStore.getState().getMedicineById(medicineId);

        if (reminderTime && medicine) {
          await scheduleMedicineNotification(medicine, reminderTime, true, true);
        }
      }

      showSuccess(
        language === 'tr' ? 'Test İlacı Eklendi' : 'Test Medicine Added',
        language === 'tr'
          ? `${randomName} (${randomDose}) eklendi.\n\nAlarm: ${newTimeStr} (${1 + offsetMinutes} dakika sonra)`
          : `${randomName} (${randomDose}) added.\n\nAlarm: ${newTimeStr} (in ${1 + offsetMinutes} minutes)`
      );
    };

    // Saat cakismasi kontrolu ile devam eden fonksiyon
    const proceedWithTimeConflictCheck = async () => {
      const timeConflictResult = checkTimeConflict();

      if (timeConflictResult.hasConflict) {
        // Cakismayan ilk saati bul (maksimum 5 dakika ileriye kadar)
        const nonConflictingResult = findNonConflictingTime(timeStr);

        if (nonConflictingResult) {
          // Cakismayan saat bulundu
          const { time: suggestedTime, offsetMinutes } = nonConflictingResult;

          showAlert({
            type: 'warning',
            title: language === 'tr' ? 'Saat Çakışması Tespit Edildi' : 'Time Conflict Detected',
            message: `${language === 'tr' ? 'Bu ilaç aşağıdaki ilaçlarla aynı saate denk geliyor:' : 'This medicine conflicts with the following medicines:'}\n\n${timeConflictResult.conflictMessages}\n\n${language === 'tr' ? 'Ne yapmak istersiniz?' : 'What would you like to do?'}`,
            buttons: [
              { text: language === 'tr' ? 'İptal' : 'Cancel', style: 'cancel' },
              {
                text: language === 'tr' ? `${suggestedTime}'e Ekle` : `Add at ${suggestedTime}`,
                onPress: () => doAddMedicineWithOffset(offsetMinutes),
              },
              {
                text: language === 'tr' ? 'Yine de Ekle' : 'Add Anyway',
                style: 'destructive',
                onPress: doAddMedicine,
              },
            ],
          });
        } else {
          // 5 dakika icinde cakismayan saat bulunamadi
          showAlert({
            type: 'warning',
            title: language === 'tr' ? 'Saat Çakışması Tespit Edildi' : 'Time Conflict Detected',
            message: `${language === 'tr' ? 'Bu ilaç aşağıdaki ilaçlarla aynı saate denk geliyor:' : 'This medicine conflicts with the following medicines:'}\n\n${timeConflictResult.conflictMessages}\n\n${language === 'tr' ? '5 dakika içinde uygun boş saat bulunamadı.' : 'No available time slot found within 5 minutes.'}`,
            buttons: [
              { text: language === 'tr' ? 'İptal' : 'Cancel', style: 'cancel' },
              {
                text: language === 'tr' ? 'Yine de Ekle' : 'Add Anyway',
                style: 'destructive',
                onPress: doAddMedicine,
              },
            ],
          });
        }
      } else {
        await doAddMedicine();
      }
    };

    // Önce ilaç etkileşimi kontrolü
    if (interactionResult.hasInteractions) {
      const interactionMessages = interactionResult.interactions
        .map(i => `${getSeverityIcon(i.severity)} ${i.drug1} + ${i.drug2}\n${i.description}`)
        .join('\n\n');

      showAlert({
        type: 'warning',
        title: language === 'tr' ? 'İlaç Etkileşimi Tespit Edildi' : 'Drug Interaction Detected',
        message: `${interactionMessages}\n\n${language === 'tr' ? 'Yine de eklemek istiyor musunuz?' : 'Do you still want to add this medicine?'}`,
        buttons: [
          { text: language === 'tr' ? 'İptal' : 'Cancel', style: 'cancel' },
          {
            text: language === 'tr' ? 'Yine de Ekle' : 'Add Anyway',
            style: 'destructive',
            onPress: proceedWithTimeConflictCheck,
          },
        ],
      });
    } else {
      await proceedWithTimeConflictCheck();
    }
  }, [addMedicine, language, medicines, reminderTimes, showSuccess, showAlert]);

  // Test ilacı ekle (10 saniye sonraya alarm) - hızlı test, çakışma kontrolü yok
  const handleAddTestMedicine10s = useCallback(async () => {
    const randomName = TEST_MEDICINE_NAMES[Math.floor(Math.random() * TEST_MEDICINE_NAMES.length)];
    const randomDose = TEST_MEDICINE_DOSES[Math.floor(Math.random() * TEST_MEDICINE_DOSES.length)];
    const randomInstruction =
      TEST_INSTRUCTIONS[Math.floor(Math.random() * TEST_INSTRUCTIONS.length)];
    const randomColor = `#${Math.floor(Math.random() * 16777215)
      .toString(16)
      .padStart(6, '0')}`;

    const alarmTime = new Date(Date.now() + 10 * 1000);
    const timeStr = format(alarmTime, 'HH:mm');
    const testMedicineName = `TEST-${randomName}`;

    const medicineId = addMedicine({
      name: testMedicineName,
      dosage: randomDose,
      frequency: 1,
      instructions: randomInstruction,
      color: randomColor,
      customTimes: [timeStr],
      startDate: new Date().toISOString(),
    });

    const hasPermission = await requestNotificationPermissions();
    if (hasPermission) {
      const newReminderTimes = useMedicineStore.getState().reminderTimes;
      const reminderTime = newReminderTimes.find(rt => rt.medicineId === medicineId);
      const medicine = useMedicineStore.getState().getMedicineById(medicineId);

      if (reminderTime && medicine) {
        // 10 saniye sonraya gerçek ilaç ID'si ile alarm planla
        const triggerTime = new Date(Date.now() + 10 * 1000);
        const notifTimeStr = triggerTime.toLocaleTimeString('tr-TR', {
          hour: '2-digit',
          minute: '2-digit',
        });
        const notifId = `alarm-${medicine.id}-${reminderTime.id}`;

        await notifee.cancelNotification(notifId);
        await notifee.createTriggerNotification(
          {
            id: notifId,
            title: `💊 ${medicine.name}`,
            subtitle: notifTimeStr,
            body: `${medicine.dosage} almanin zamani!\n⏰ ${notifTimeStr}`,
            android: {
              channelId: CHANNELS.ALARM,
              category: 'alarm' as any,
              importance: 4, // HIGH
              visibility: 1, // PUBLIC
              ongoing: true,
              autoCancel: false,
              onlyAlertOnce: false,
              loopSound: true,
              fullScreenAction: {
                id: 'default',
                launchActivity: 'com.ilachatirlatici.MainActivity',
              },
              pressAction: { id: 'default', launchActivity: 'com.ilachatirlatici.MainActivity' },
              smallIcon: 'ic_launcher',
              color: '#2196F3',
              colorized: true,
              sound: 'alarm',
              vibrationPattern: [500, 1000, 500, 1000, 500, 1000],
              actions: [
                { title: '😴 Ertele', pressAction: { id: 'snooze' } },
                { title: '✅ Aldım', pressAction: { id: 'take' } },
              ],
            },
            data: {
              medicineId: medicine.id,
              reminderTimeId: reminderTime.id,
              scheduledTime: triggerTime.toISOString(),
              fullScreenAlarm: 'true',
            },
          },
          {
            type: 1, // TIMESTAMP
            timestamp: triggerTime.getTime(),
            alarmManager: { allowWhileIdle: true, type: 2 }, // SET_ALARM_CLOCK
          }
        );
      }
    }

    showSuccess(
      language === 'tr' ? 'Test İlacı Eklendi (10sn)' : 'Test Medicine Added (10s)',
      language === 'tr'
        ? `${randomName} (${randomDose}) eklendi.\n\nAlarm: 10 saniye sonra`
        : `${randomName} (${randomDose}) added.\n\nAlarm: in 10 seconds`
    );
  }, [addMedicine, language, showSuccess]);

  // Test ilaçlarını sil (TEST- prefix'li olanlar)
  const handleDeleteTestMedicines = useCallback(() => {
    const testMedicines = medicines.filter(m => m.name.startsWith('TEST-'));

    if (testMedicines.length === 0) {
      showInfo(
        language === 'tr' ? 'Bilgi' : 'Info',
        language === 'tr' ? 'Silinecek test ilacı yok.' : 'No test medicines to delete.'
      );
      return;
    }

    showConfirm(
      language === 'tr' ? 'Test İlaçlarını Sil' : 'Delete Test Medicines',
      language === 'tr'
        ? `${testMedicines.length} adet test ilacı silinecek. Emin misiniz?`
        : `${testMedicines.length} test medicines will be deleted. Are you sure?`,
      () => {
        testMedicines.forEach(m => deleteMedicine(m.id));
        showSuccess(
          t('success'),
          language === 'tr'
            ? `${testMedicines.length} test ilacı silindi.`
            : `${testMedicines.length} test medicines deleted.`
        );
      },
      {
        confirmText: language === 'tr' ? 'Sil' : 'Delete',
        cancelText: language === 'tr' ? 'İptal' : 'Cancel',
        destructive: true,
      }
    );
  }, [medicines, deleteMedicine, language, t, showInfo, showConfirm, showSuccess]);

  const handleShowScheduledNotifications = useCallback(async () => {
    try {
      const triggerIds = await notifee.getTriggerNotificationIds();
      const displayedNotifs = await notifee.getDisplayedNotifications();

      const medicineInfo = medicines
        .map(m => {
          const times = reminderTimes.filter(rt => rt.medicineId === m.id);
          return `${m.name}: ${times.map(t => t.time).join(', ')}`;
        })
        .join('\n');

      const triggerInfo =
        triggerIds.length > 0
          ? triggerIds.join('\n')
          : language === 'tr'
            ? 'Hiç planlanmış bildirim yok!'
            : 'No scheduled notifications!';

      showInfo(
        language === 'tr' ? 'Debug Bilgisi' : 'Debug Info',
        `${language === 'tr' ? 'İlaçlar' : 'Medicines'} (${medicines.length}):\n${medicineInfo || 'Yok'}\n\n` +
          `${language === 'tr' ? 'Planlanmış Bildirimler' : 'Scheduled Notifications'} (${triggerIds.length}):\n${triggerInfo}\n\n` +
          `${language === 'tr' ? 'Görüntülen Bildirimler' : 'Displayed Notifications'}: ${displayedNotifs.length}`
      );
    } catch (error) {
      log.error('Debug bilgisi alınamadı', error);
      showError('Error', String(error));
    }
  }, [medicines, reminderTimes, language, showInfo, showError]);

  // Tüm verileri temizle (Firebase ve local)
  const handleClearAllData = useCallback(() => {
    showInfo(
      language === 'tr' ? 'ℹ️ Bilgi' : 'ℹ️ Info',
      language === 'tr'
        ? 'Bu özellik yakında aktif olacak. Lütfen Firebase Console üzerinden manuel temizlik yapın.'
        : 'This feature will be available soon. Please clean manually via Firebase Console.'
    );
  }, [showInfo, language]);

  const handleLogout = useCallback(() => {
    showConfirm(
      language === 'tr' ? 'Çıkış Yap' : 'Logout',
      language === 'tr'
        ? 'Hesabınızdan çıkış yapmak istediğinize emin misiniz?'
        : 'Are you sure you want to logout?',
      async () => {
        try {
          await syncToCloud();
          await logout();
        } catch (error) {
          log.error('Logout error', error);
        }
      },
      {
        confirmText: language === 'tr' ? 'Çıkış Yap' : 'Logout',
        cancelText: t('cancel'),
        destructive: true,
      }
    );
  }, [language, logout, syncToCloud, t, showConfirm]);

  const formatLastSync = useCallback(() => {
    if (!lastSyncAt) {
      return language === 'tr' ? 'Henüz senkronize edilmedi' : 'Never synced';
    }
    const date = new Date(lastSyncAt);
    return format(date, 'dd.MM.yyyy HH:mm');
  }, [language, lastSyncAt]);

  const formatTimeDisplay = useCallback((time: string) => {
    const [hours, minutes] = time.split(':').map(Number);
    return `${hours.toString().padStart(2, '0')}:${minutes.toString().padStart(2, '0')}`;
  }, []);

  const getThemeLabel = useCallback(
    (themeValue: ThemeMode) => {
      switch (themeValue) {
        case 'light':
          return t('settings_theme_light');
        case 'dark':
          return t('settings_theme_dark');
        case 'system':
          return t('settings_theme_system');
      }
    },
    [t]
  );

  const getLanguageLabel = useCallback((lang: Language) => {
    return lang === 'tr' ? 'Türkçe' : 'English';
  }, []);

  return {
    navigation,
    colors,
    isDark,
    theme,
    setTheme,
    language,
    setLanguage,
    t,
    settings,
    updateSettings,
    isSyncing,
    user,
    isPremium,
    remainingDays,
    pickerState,
    togglePicker,
    closePicker,
    parseTimeToDate,
    handleTimeChange,
    handleTestNotification,
    handleTestVoice,
    handleTestFullScreenAlarm,
    handleScheduleTestAlarm,
    handleAddTestMedicine,
    handleAddTestMedicine10s,
    handleDeleteTestMedicines,
    handleShowScheduledNotifications,
    handleClearAllData,
    handleSync,
    handleLogout,
    formatLastSync,
    formatTimeDisplay,
    getThemeLabel,
    getLanguageLabel,
  };
}

import React, { useEffect, useRef, useMemo, useCallback } from 'react';
import {
  View,
  Text,
  StyleSheet,
  TouchableOpacity,
  Vibration,
  Dimensions,
  Animated,
} from 'react-native';
import { useNavigation, useRoute, RouteProp } from '@react-navigation/native';
import { NativeStackNavigationProp } from '@react-navigation/native-stack';
import notifee, { EventType } from '@notifee/react-native';
import { playAlarmSound, stopAlarmSound } from '../utils/alarmSoundManager';
import ReactNativeHapticFeedback from 'react-native-haptic-feedback';
import { useMedicineStore } from '../stores/medicineStore';
import { RootStackParamList, ReminderTime } from '../types';
import { stopAdvancedSpeaking, speakAlarmNotification } from '../utils/advancedSpeech';
import {
  scheduleSnoozeNotification,
  scheduleMedicineNotification,
  dismissNotification,
  cancelNotification,
  cancelMedicineNotifications,
} from '../utils/notifications';
import { generateId } from '../utils/idGenerator';
import { format } from 'date-fns';
import { tr, enUS } from 'date-fns/locale';
import { useLanguage } from '../contexts/LanguageContext';
import { createScopedLogger } from '../utils/logger';

const log = createScopedLogger('AlarmScreen');

type NavigationProp = NativeStackNavigationProp<RootStackParamList>;
type RouteProps = RouteProp<RootStackParamList, 'Alarm'>;

const { width, height } = Dimensions.get('window');

export default function AlarmScreen() {
  const navigation = useNavigation<NavigationProp>();
  const route = useRoute<RouteProps>();
  const {
    medicineId,
    reminderTimeId,
    scheduledTime,
    snoozeCount: routeSnoozeCount,
    originalScheduledTime: routeOriginalScheduledTime,
  } = route.params;
  const { t, language } = useLanguage();

  const dateLocale = language === 'tr' ? tr : enUS;

  const {
    getMedicineById,
    getReminderTimesForMedicine,
    logMedicineTaken,
    logMedicineSkipped,
    dismissAlarm,
    settings,
    createSnooze,
    snoozes,
  } = useMedicineStore();

  // Test modu kontrolü
  const isTestMode = medicineId === 'test-medicine';

  // Test için örnek ilaç - useMemo ile SADECE BİR KEZ oluştur
  const testMedicine = useMemo(
    () => ({
      id: 'test-medicine',
      name: 'Aspirin',
      dosage: '500mg',
      frequency: 2,
      instructions: 'after_meal' as const,
      color: '#FF6B6B',
      startDate: '2024-01-01T00:00:00.000Z', // Sabit değer
      isActive: true,
      createdAt: '2024-01-01T00:00:00.000Z', // Sabit değer
      updatedAt: '2024-01-01T00:00:00.000Z', // Sabit değer
    }),
    []
  ); // Boş dependency - sadece bir kez oluşur

  const medicine = isTestMode ? testMedicine : getMedicineById(medicineId);
  const reminderTimes = medicine && !isTestMode ? getReminderTimesForMedicine(medicine.id) : [];
  const currentReminderTime = reminderTimes.find(rt => rt.id === reminderTimeId);

  // Erteleme süresi ve limiti ayarlardan al
  const snoozeDuration = settings.snoozeDuration || 5;
  const maxSnoozeCount = settings.maxSnoozeCount || 3;

  // Mevcut snooze sayısını hesapla
  // Background'dan geliyorsa routeSnoozeCount kullan, yoksa snoozes array'den hesapla
  const currentSnoozeCount = useMemo(() => {
    // Route params'tan gelen snoozeCount varsa (background snooze'dan geldiyse)
    if (routeSnoozeCount !== undefined && routeSnoozeCount > 0) {
      return routeSnoozeCount;
    }
    // Yoksa snoozes array'den hesapla
    if (!medicine) return 0;
    const originalTime = routeOriginalScheduledTime || scheduledTime || new Date().toISOString();
    const reminderTimeToCheck = currentReminderTime?.id || 'test-reminder';
    return snoozes.filter(
      s =>
        s.medicineId === medicine.id &&
        s.reminderTimeId === reminderTimeToCheck &&
        s.originalScheduledTime === originalTime
    ).length;
  }, [
    medicine,
    currentReminderTime,
    scheduledTime,
    snoozes,
    routeSnoozeCount,
    routeOriginalScheduledTime,
  ]);

  // Erteleme hakkı kaldı mı?
  const canSnooze = currentSnoozeCount < maxSnoozeCount;
  const remainingSnoozes = maxSnoozeCount - currentSnoozeCount;

  const pulseAnim = useRef(new Animated.Value(1)).current;
  const vibrationIntervalRef = useRef<NodeJS.Timeout | null>(null);
  const ttsTimeoutRef = useRef<NodeJS.Timeout | null>(null);
  const isStoppedRef = useRef<boolean>(false); // Alarm durduruldu mu?
  const isSnoozingRef = useRef<boolean>(false); // Snooze işlemi devam ediyor mu?

  // Pulse animasyonu
  useEffect(() => {
    const pulse = Animated.loop(
      Animated.sequence([
        Animated.timing(pulseAnim, {
          toValue: 1.1,
          duration: 800,
          useNativeDriver: true,
        }),
        Animated.timing(pulseAnim, {
          toValue: 1,
          duration: 800,
          useNativeDriver: true,
        }),
      ])
    );
    pulse.start();

    return () => pulse.stop();
  }, []);

  // Alarm durdurma fonksiyonu - useEffect'lerden önce tanımlanmalı
  const stopAlarm = useCallback(async () => {
    log.debug('stopAlarm basladi');

    isStoppedRef.current = true;

    if (vibrationIntervalRef.current) {
      clearInterval(vibrationIntervalRef.current);
      vibrationIntervalRef.current = null;
    }

    Vibration.cancel();

    if (ttsTimeoutRef.current) {
      clearTimeout(ttsTimeoutRef.current);
      ttsTimeoutRef.current = null;
    }

    try {
      await stopAdvancedSpeaking();
    } catch (e) {
      log.debug('stopSpeaking hatasi', { error: e });
    }

    await stopAlarmSound();

    Vibration.cancel();

    log.debug('stopAlarm bitti');
  }, []);

  // Alarm ekranı açıldığında bildirimi kapat
  useEffect(() => {
    // Bildirimi hemen kapat - kullanıcı alarm ekranını gördü
    dismissNotification(`alarm-${medicineId}-${reminderTimeId}`);
    log.debug('Alarm ekrani acildi, bildirim kapatildi');
  }, [medicineId, reminderTimeId]);

  // CRITICAL: Background'dan gelen notification action'larını dinle
  // Kullanıcı bildirimden butona bastığında AlarmScreen açık olabilir - sesi durdurmak için gerekli
  useEffect(() => {
    const unsubscribe = notifee.onForegroundEvent(async ({ type, detail }) => {
      log.debug('Foreground event alindi', {
        type,
        notificationId: detail.notification?.id,
        pressAction: detail.pressAction?.id,
      });

      if (type === EventType.ACTION_PRESS) {
        const actionId = detail.pressAction?.id;
        const notificationMedicineId = detail.notification?.data?.medicineId as string;

        if (
          notificationMedicineId === medicineId ||
          detail.notification?.id?.includes(medicineId)
        ) {
          log.debug('Bu alarm icin action algilandi, ses durduruluyor', { actionId });

          await stopAlarm();

          dismissAlarm();
          if (navigation.canGoBack()) {
            navigation.goBack();
          } else {
            navigation.reset({
              index: 0,
              routes: [{ name: 'Main' }],
            });
          }
        }
      }

      if (type === EventType.DISMISSED) {
        const notificationMedicineId = detail.notification?.data?.medicineId as string;
        if (
          notificationMedicineId === medicineId ||
          detail.notification?.id?.includes(medicineId)
        ) {
          log.debug('Notification dismissed, ses durduruluyor');
          await stopAlarm();
        }
      }
    });

    return () => unsubscribe();
  }, [medicineId, stopAlarm, dismissAlarm, navigation]);

  // İLAÇ BULUNAMADIĞINDA: Alarmı durdur ve ana ekrana yönlendir
  useEffect(() => {
    if (!medicine && !isTestMode) {
      log.debug('PHANTOM ALARM ALGILANDI - Ilac bulunamadi, hemen kapatiliyor', { medicineId });

      // HEMEN alarm flag'ini set et - ses/titreşim başlamasını engelle
      isStoppedRef.current = true;

      // Titreşimi HEMEN durdur
      Vibration.cancel();

      // Bildirimi iptal et
      dismissNotification(`alarm-${medicineId}-${reminderTimeId}`);

      // Tüm phantom bildirimleri temizle
      cancelMedicineNotifications(medicineId);

      // Alarm state'ini temizle
      dismissAlarm();

      // Navigation RESET ile ana ekrana dön - bu her zaman çalışır
      navigation.reset({
        index: 0,
        routes: [{ name: 'Main' }],
      });
    }
  }, [medicine, isTestMode, medicineId, reminderTimeId, navigation, dismissAlarm]);

  // Titreşim, ses ve TTS
  useEffect(() => {
    // İlaç yoksa (silinmiş/phantom) ses ve titreşim başlatma
    if (!medicine && !isTestMode) {
      log.debug('Ilac bulunamadi, ses/titresim baslatilmiyor');
      return;
    }

    // Eğer alarm zaten durdurulduysa (phantom guard tarafından), başlatma
    if (isStoppedRef.current) {
      log.debug('Alarm zaten durduruldu, ses/titresim baslatilmiyor');
      return;
    }

    // Reset stopped flag - sadece normal alarm için
    isStoppedRef.current = false;

    // Titreşim pattern (sürekli)
    const vibrationPattern = [0, 500, 500, 500];

    // İlk titreşim
    if (settings.vibrationEnabled && !isStoppedRef.current) {
      Vibration.vibrate(vibrationPattern);
    }

    // Tekrarlayan titreşim - ref'te sakla
    vibrationIntervalRef.current = setInterval(() => {
      // Eğer alarm durdurulduysa, interval'i temizle ve çık
      if (isStoppedRef.current) {
        if (vibrationIntervalRef.current) {
          clearInterval(vibrationIntervalRef.current);
          vibrationIntervalRef.current = null;
        }
        return;
      }
      if (settings.vibrationEnabled) {
        Vibration.vibrate(vibrationPattern);
      }
    }, 2000);

    ReactNativeHapticFeedback.trigger('notificationWarning', {
      enableVibrateFallback: true,
      ignoreAndroidSystemSettings: false,
    });

    if (!isStoppedRef.current) {
      playAlarmSound(settings.alarmVolume ?? 80);
    }

    if (medicine) {
      const speakReminder = async () => {
        if (isStoppedRef.current) {
          log.debug('Alarm durduruldu, TTS baslatilmiyor');
          return;
        }
        try {
          await speakAlarmNotification(
            medicine.name,
            medicine.dosage,
            medicine.instructions,
            language,
            {
              ttsEnabled: settings.ttsEnabled,
              ttsVolume: settings.ttsVolume,
              ttsRepeatCount: settings.ttsRepeatCount,
              ttsSpeakMedicineName: settings.ttsSpeakMedicineName,
              ttsSpeakDosage: settings.ttsSpeakDosage,
              ttsSpeakInstructions: settings.ttsSpeakInstructions,
            }
          );
        } catch (error) {
          log.debug('TTS hatasi', { error });
        }
      };
      ttsTimeoutRef.current = setTimeout(speakReminder, 1000);
    }

    return () => {
      if (ttsTimeoutRef.current) {
        clearTimeout(ttsTimeoutRef.current);
        ttsTimeoutRef.current = null;
      }
      if (vibrationIntervalRef.current) {
        clearInterval(vibrationIntervalRef.current);
        vibrationIntervalRef.current = null;
      }
      Vibration.cancel();
      stopAdvancedSpeaking();
      stopAlarmSound();
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [medicine, isTestMode, medicineId, settings.vibrationEnabled, language]);

  const handleTake = async () => {
    await stopAlarm();
    // KRİTİK: scheduledTime'ı HomeScreen ile aynı formatta oluştur
    // getTodayReminders `l.scheduledTime.startsWith(today)` ile eşleştirir
    // toISOString() UTC verir, gece saatlerinde tarih uyuşmaz
    const todayStr = format(new Date(), 'yyyy-MM-dd');
    const timeStr = currentReminderTime?.time || format(new Date(), 'HH:mm');
    const logTime = `${todayStr}T${timeStr}:00`;
    log.debug('handleTake called', { isTestMode, reminderTimeId, logTime, medicineId });
    if (!isTestMode) {
      logMedicineTaken(reminderTimeId, logTime, medicineId);
      log.debug('logMedicineTaken called from handleTake with medicineId fallback');
    } else {
      log.debug('Test mode - take not logged');
    }
    const notificationId = `alarm-${medicineId}-${reminderTimeId}`;
    // Hem displayed hem trigger notification'ı iptal et
    await dismissNotification(notificationId);
    await cancelNotification(notificationId);

    // Yarın için alarmı yeniden planla (günlük tekrar için)
    if (medicine && currentReminderTime && !isTestMode) {
      try {
        await scheduleMedicineNotification(medicine, currentReminderTime, true);
        log.debug('Yarin icin alarm yeniden planlandi', { time: currentReminderTime.time });
      } catch (e) {
        log.debug('Alarm yeniden planlama hatasi', { error: e });
      }
    }

    dismissAlarm();
    navigation.goBack();
  };

  const handleSkip = async () => {
    await stopAlarm();
    // KRİTİK: scheduledTime'ı HomeScreen ile aynı formatta oluştur
    const todayStr = format(new Date(), 'yyyy-MM-dd');
    const timeStr = currentReminderTime?.time || format(new Date(), 'HH:mm');
    const logTime = `${todayStr}T${timeStr}:00`;
    log.debug('handleSkip called', { isTestMode, reminderTimeId, logTime, medicineId });
    if (!isTestMode) {
      logMedicineSkipped(reminderTimeId, logTime, medicineId);
      log.debug('logMedicineSkipped called from handleSkip with medicineId fallback');
    } else {
      log.debug('Test mode - skip not logged');
    }
    const notificationId = `alarm-${medicineId}-${reminderTimeId}`;
    // Hem displayed hem trigger notification'ı iptal et
    await dismissNotification(notificationId);
    await cancelNotification(notificationId);

    // Yarın için alarmı yeniden planla (günlük tekrar için)
    if (medicine && currentReminderTime && !isTestMode) {
      try {
        await scheduleMedicineNotification(medicine, currentReminderTime, true);
        log.debug('Yarin icin alarm yeniden planlandi', { time: currentReminderTime.time });
      } catch (e) {
        log.debug('Alarm yeniden planlama hatasi', { error: e });
      }
    }

    dismissAlarm();
    navigation.goBack();
  };

  const handleSnooze = async () => {
    // Double-tap koruması
    if (isSnoozingRef.current) {
      log.debug('handleSnooze zaten çalışıyor, atlanıyor');
      return;
    }

    // Erteleme limiti tamamen dolmuşsa (olmaması lazım ama güvenlik)
    if (!canSnooze) {
      log.debug('Erteleme limiti doldu', { currentSnoozeCount, maxSnoozeCount });
      await handleSkip();
      return;
    }

    // Son hak — ertele basıldığında ilaç atlanır, yeni alarm planlanmaz
    if (remainingSnoozes === 1) {
      log.debug('Son erteleme hakkı kullanıldı, ilaç atlanıyor', {
        currentSnoozeCount,
        maxSnoozeCount,
      });
      await handleSkip();
      return;
    }

    isSnoozingRef.current = true;

    log.debug('handleSnooze basladi', { currentSnoozeCount, remainingSnoozes });

    try {
      await stopAlarm();
    } catch (error) {
      log.debug('stopAlarm hatasi', { error });
    }

    const notificationId = `alarm-${medicineId}-${reminderTimeId}`;

    // KRİTİK: Hem displayed hem trigger notification'ı iptal et
    // dismissNotification sadece displayed'ı kapatır, trigger aktif kalır
    // cancelNotification ikisini de iptal eder
    try {
      await dismissNotification(notificationId);
      await cancelNotification(notificationId);
      log.debug('Bildirimler iptal edildi (displayed + trigger)', { notificationId });
    } catch (error) {
      log.debug('Bildirim iptal hatasi', { error });
    }

    dismissAlarm();

    if (medicine) {
      const testReminderTime: ReminderTime = {
        id: 'test-reminder',
        medicineId: medicine.id,
        time: format(new Date(), 'HH:mm'),
        isEnabled: true,
      };

      const reminderTimeToUse = currentReminderTime || testReminderTime;
      const snoozeId = generateId();
      const originalScheduledTime = scheduledTime || new Date().toISOString();

      // KRİTİK: currentSnoozeCount kullan (route params veya snoozes array'den zaten doğru hesaplandı)
      // existingSnoozeCount kullanma - background snoozeler snoozes array'e eklenmediği için uyumsuz
      const newSnoozeCount = currentSnoozeCount + 1;

      log.debug('Snooze planlanıyor', {
        currentSnoozeCount,
        newSnoozeCount,
        maxSnoozeCount,
      });

      try {
        const result = await scheduleSnoozeNotification({
          medicine,
          reminderTime: reminderTimeToUse,
          snoozeDuration,
          snoozeId,
          originalScheduledTime,
          snoozeCount: newSnoozeCount,
        });

        if (result) {
          createSnooze(
            medicine.id,
            reminderTimeToUse.id,
            originalScheduledTime,
            result.triggerTime,
            result.notificationId
          );
          log.debug("Ilac ertelendi ve DB'ye kaydedildi", {
            snoozeDuration,
            notificationId: result.notificationId,
            triggerTime: result.triggerTime.toISOString(),
          });
        } else {
          log.error('Snooze planlanamadi - result null');
        }
      } catch (e) {
        log.error('scheduleSnoozeNotification hatasi', { error: e });
      }

      // Yarın için günlük alarmı yeniden planla (snooze ayrı bildirim, bu günlük tekrar için)
      if (currentReminderTime && !isTestMode) {
        try {
          await scheduleMedicineNotification(medicine, currentReminderTime, true);
          log.debug('Yarin icin alarm yeniden planlandi', { time: currentReminderTime.time });
        } catch (e) {
          log.debug('Alarm yeniden planlama hatasi', { error: e });
        }
      }
    }

    // goBack çağır
    if (navigation.canGoBack()) {
      navigation.goBack();
    } else {
      navigation.navigate('Main');
    }

    log.debug('handleSnooze bitti');
  };

  // İlaç bulunamadı - bu ekran görünmemeli, useEffect geri dönmeli
  // Ama navigation başarısız olursa bu görünür
  if (!medicine) {
    // Test modu değilse ana ekrana dön
    if (!isTestMode) {
      // Fallback: 500ms sonra tekrar navigation dene
      setTimeout(() => {
        navigation.reset({
          index: 0,
          routes: [{ name: 'Main' }],
        });
      }, 500);
    }

    return (
      <View
        style={[
          styles.container,
          { backgroundColor: '#333', justifyContent: 'center', alignItems: 'center' },
        ]}
      >
        <Text style={styles.errorText}>
          {language === 'tr'
            ? 'İlaç bulunamadı, ana ekrana dönülüyor...'
            : 'Medicine not found, returning to home...'}
        </Text>
        <TouchableOpacity
          style={{ marginTop: 20, padding: 15, backgroundColor: '#4ECDC4', borderRadius: 10 }}
          onPress={() => {
            navigation.reset({
              index: 0,
              routes: [{ name: 'Main' }],
            });
          }}
        >
          <Text style={{ color: '#fff', fontSize: 16, fontWeight: 'bold' }}>
            {language === 'tr' ? 'Ana Ekrana Dön' : 'Go to Home'}
          </Text>
        </TouchableOpacity>
      </View>
    );
  }

  const currentTime = format(new Date(), 'HH:mm');
  const currentDate = format(new Date(), 'dd MMMM yyyy', { locale: dateLocale });

  // Talimat metni
  const getInstructionDisplay = () => {
    if (!medicine.instructions) return null;

    const instructionTexts: Record<string, { tr: string; en: string }> = {
      before_meal: { tr: '🍽️ Yemekten önce', en: '🍽️ Before meal' },
      after_meal: { tr: '🍽️ Yemekten sonra', en: '🍽️ After meal' },
      with_meal: { tr: '🍽️ Yemekle birlikte', en: '🍽️ With meal' },
      empty_stomach: { tr: '⚠️ Aç karnına', en: '⚠️ Empty stomach' },
      before_sleep: { tr: '🌙 Yatmadan önce', en: '🌙 Before sleep' },
    };

    return instructionTexts[medicine.instructions]?.[language] || null;
  };

  return (
    <View style={[styles.container, { backgroundColor: medicine.color }]}>
      {/* Üst kısım - Saat */}
      <View style={styles.timeSection}>
        <Text style={styles.currentTime}>{currentTime}</Text>
        <Text style={styles.currentDate}>{currentDate}</Text>
      </View>

      {/* Orta kısım - İlaç bilgisi */}
      <View style={styles.medicineSection}>
        <Animated.View style={[styles.iconContainer, { transform: [{ scale: pulseAnim }] }]}>
          <Text style={styles.medicineIcon}>💊</Text>
        </Animated.View>

        <Text style={styles.alarmTitle}>{t('alarm_time_to_take')}</Text>
        <Text style={styles.medicineName}>{medicine.name}</Text>
        <Text style={styles.dosageText}>{medicine.dosage}</Text>

        {getInstructionDisplay() && (
          <View style={styles.instructionBadge}>
            <Text style={styles.instructionText}>{getInstructionDisplay()}</Text>
          </View>
        )}
      </View>

      {/* Alt kısım - Butonlar */}
      <View style={styles.actionSection}>
        {/* Ana buton - Aldım */}
        <TouchableOpacity style={styles.takeButton} onPress={handleTake} activeOpacity={0.8}>
          <Text style={styles.takeButtonIcon}>✓</Text>
          <Text style={styles.takeButtonText}>{t('alarm_take_now')}</Text>
        </TouchableOpacity>

        {/* Erteleme butonu */}
        <TouchableOpacity
          style={[styles.snoozeButton, !canSnooze && styles.snoozeButtonDisabled]}
          onPress={handleSnooze}
          activeOpacity={0.8}
        >
          <Text style={[styles.snoozeButtonText, !canSnooze && styles.snoozeButtonTextDisabled]}>
            {(() => {
              const durationLabel =
                snoozeDuration < 1
                  ? `${Math.round(snoozeDuration * 60)} ${language === 'tr' ? 'sn' : 'sec'}`
                  : `${snoozeDuration} ${language === 'tr' ? 'dk' : 'min'}`;
              if (!canSnooze) {
                return `❌ ${language === 'tr' ? 'Erteleme hakkın bitti' : 'No snoozes left'}`;
              }
              if (remainingSnoozes === 1) {
                return `⚠️ ${language === 'tr' ? 'Ertele — Son hak! (İlaç atlanır)' : 'Snooze — Last chance! (Medicine skipped)'}`;
              }
              return `⏰ ${durationLabel} ${language === 'tr' ? 'ertele' : 'snooze'} — ${language === 'tr' ? `${remainingSnoozes} hak` : `${remainingSnoozes} left`}`;
            })()}
          </Text>
        </TouchableOpacity>
      </View>
    </View>
  );
}

