import React, { useState, useEffect } from 'react';
import {
  View,
  Text,
  StyleSheet,
  TouchableOpacity,
  ScrollView,
  Platform,
  ActivityIndicator,
} from 'react-native';
import { SafeAreaView } from 'react-native-safe-area-context';
import Ionicons from 'react-native-vector-icons/Ionicons';
import { useTheme, ThemeColors } from '../contexts/ThemeContext';
import { useLanguage } from '../contexts/LanguageContext';
import {
  checkAllPermissions,
  requestNotificationPermissions,
  requestExactAlarmPermission,
  requestBatteryOptimizationPermission,
  openDndSettings,
  openNotificationSettings,
  openFullScreenIntentSettings,
  openPowerManagerSettings,
} from '../utils/notifications';

interface PermissionsScreenProps {
  onComplete: () => void;
}

interface PermissionStatus {
  notifications: boolean;
  exactAlarm: boolean;
  batteryOptimization: boolean;
  dnd: boolean;
  fullScreenIntent: boolean;
  powerManagerRestricted: boolean;
  manufacturer: string | null;
}

export default function PermissionsScreen({ onComplete }: PermissionsScreenProps) {
  const { colors } = useTheme();
  const { language } = useLanguage();
  const [permissions, setPermissions] = useState<PermissionStatus | null>(null);
  const [isLoading, setIsLoading] = useState(true);
  const [isRequesting, setIsRequesting] = useState(false);

  const checkPermissions = async () => {
    setIsLoading(true);
    const status = await checkAllPermissions();
    setPermissions(status);
    setIsLoading(false);
  };

  useEffect(() => {
    checkPermissions();
  }, []);

  const handleRequestNotifications = async () => {
    setIsRequesting(true);
    await requestNotificationPermissions();
    await checkPermissions();
    setIsRequesting(false);
  };

  const handleRequestExactAlarm = async () => {
    await requestExactAlarmPermission();
    // Ayarlardan döndükten sonra kontrol et
    setTimeout(checkPermissions, 1000);
  };

  const handleRequestBatteryOptimization = async () => {
    await requestBatteryOptimizationPermission();
    setTimeout(checkPermissions, 1000);
  };

  const handleOpenDndSettings = async () => {
    await openDndSettings();
    setTimeout(checkPermissions, 1000);
  };

  const handleOpenNotificationSettings = async () => {
    await openNotificationSettings();
    setTimeout(checkPermissions, 1000);
  };

  const handleOpenFullScreenIntentSettings = async () => {
    await openFullScreenIntentSettings();
    setTimeout(checkPermissions, 1000);
  };

  const handleOpenPowerManagerSettings = async () => {
    await openPowerManagerSettings();
    setTimeout(checkPermissions, 1000);
  };

  // Battery optimization ve Power Manager kritik izinler olarak eklendi
  const allPermissionsGranted = permissions &&
    permissions.notifications &&
    permissions.exactAlarm &&
    permissions.batteryOptimization;

  const styles = createStyles(colors);

  if (isLoading) {
    return (
      <SafeAreaView style={styles.container}>
        <View style={styles.loadingContainer}>
          <ActivityIndicator size="large" color={colors.primary} />
        </View>
      </SafeAreaView>
    );
  }

  return (
    <SafeAreaView style={styles.container}>
      <ScrollView contentContainerStyle={styles.scrollContent}>
        {/* Header */}
        <View style={styles.header}>
          <View style={styles.iconContainer}>
            <Ionicons name="notifications" size={48} color={colors.primary} />
          </View>
          <Text style={styles.title}>
            {language === 'tr' ? 'İzinler Gerekli' : 'Permissions Required'}
          </Text>
          <Text style={styles.subtitle}>
            {language === 'tr' 
              ? 'İlaç hatırlatmalarının düzgün çalışması için aşağıdaki izinlere ihtiyacımız var.'
              : 'We need the following permissions for medication reminders to work properly.'}
          </Text>
        </View>

        {/* Permission Items */}
        <View style={styles.permissionsContainer}>
          {/* Bildirim İzni */}
          <View style={styles.permissionItem}>
            <View style={styles.permissionInfo}>
              <View style={[styles.permissionIcon, { backgroundColor: permissions?.notifications ? '#10B98120' : '#EF444420' }]}>
                <Ionicons 
                  name={permissions?.notifications ? "checkmark-circle" : "notifications-outline"} 
                  size={24} 
                  color={permissions?.notifications ? '#10B981' : '#EF4444'} 
                />
              </View>
              <View style={styles.permissionText}>
                <Text style={styles.permissionTitle}>
                  {language === 'tr' ? 'Bildirimler' : 'Notifications'}
                </Text>
                <Text style={styles.permissionDescription}>
                  {language === 'tr' 
                    ? 'İlaç saati geldiğinde sizi uyarmak için' 
                    : 'To alert you when it\'s time for medication'}
                </Text>
              </View>
            </View>
            {!permissions?.notifications && (
              <TouchableOpacity 
                style={styles.permissionButton}
                onPress={handleRequestNotifications}
                disabled={isRequesting}
              >
                <Text style={styles.permissionButtonText}>
                  {language === 'tr' ? 'İzin Ver' : 'Allow'}
                </Text>
              </TouchableOpacity>
            )}
            {permissions?.notifications && (
              <Ionicons name="checkmark-circle" size={24} color="#10B981" />
            )}
          </View>

          {/* Kesin Alarm İzni (Android 12+) */}
          {Platform.OS === 'android' && (
            <View style={styles.permissionItem}>
              <View style={styles.permissionInfo}>
                <View style={[styles.permissionIcon, { backgroundColor: permissions?.exactAlarm ? '#10B98120' : '#F59E0B20' }]}>
                  <Ionicons 
                    name={permissions?.exactAlarm ? "checkmark-circle" : "alarm-outline"} 
                    size={24} 
                    color={permissions?.exactAlarm ? '#10B981' : '#F59E0B'} 
                  />
                </View>
                <View style={styles.permissionText}>
                  <Text style={styles.permissionTitle}>
                    {language === 'tr' ? 'Kesin Alarm' : 'Exact Alarm'}
                  </Text>
                  <Text style={styles.permissionDescription}>
                    {language === 'tr' 
                      ? 'Alarmların tam zamanında çalması için' 
                      : 'For alarms to trigger at exact times'}
                  </Text>
                </View>
              </View>
              {!permissions?.exactAlarm && (
                <TouchableOpacity 
                  style={styles.permissionButton}
                  onPress={handleRequestExactAlarm}
                >
                  <Text style={styles.permissionButtonText}>
                    {language === 'tr' ? 'Ayarla' : 'Set'}
                  </Text>
                </TouchableOpacity>
              )}
              {permissions?.exactAlarm && (
                <Ionicons name="checkmark-circle" size={24} color="#10B981" />
              )}
            </View>
          )}

          {/* Tam Ekran Bildirim İzni (Android 14+) */}
          {Platform.OS === 'android' && Platform.Version >= 34 && (
            <View style={styles.permissionItem}>
              <View style={styles.permissionInfo}>
                <View style={[styles.permissionIcon, { backgroundColor: permissions?.fullScreenIntent ? '#10B98120' : '#EF444420' }]}>
                  <Ionicons
                    name={permissions?.fullScreenIntent ? "checkmark-circle" : "expand-outline"}
                    size={24}
                    color={permissions?.fullScreenIntent ? '#10B981' : '#EF4444'}
                  />
                </View>
                <View style={styles.permissionText}>
                  <Text style={styles.permissionTitle}>
                    {language === 'tr' ? 'Tam Ekran Bildirim' : 'Full Screen Notifications'}
                  </Text>
                  <Text style={styles.permissionDescription}>
                    {language === 'tr'
                      ? 'İlaç saatinde tam ekran alarm göstermek için (kritik)'
                      : 'To show full screen alarm at medication time (critical)'}
                  </Text>
                </View>
              </View>
              {!permissions?.fullScreenIntent && (
                <TouchableOpacity
                  style={styles.permissionButton}
                  onPress={handleOpenFullScreenIntentSettings}
                >
                  <Text style={styles.permissionButtonText}>
                    {language === 'tr' ? 'Ayarla' : 'Set'}
                  </Text>
                </TouchableOpacity>
              )}
              {permissions?.fullScreenIntent && (
                <Ionicons name="checkmark-circle" size={24} color="#10B981" />
              )}
            </View>
          )}

          {/* Pil Optimizasyonu (KRITIK - Zorunlu) */}
          {Platform.OS === 'android' && (
            <View style={styles.permissionItem}>
              <View style={styles.permissionInfo}>
                <View style={[styles.permissionIcon, { backgroundColor: permissions?.batteryOptimization ? '#10B98120' : '#EF444420' }]}>
                  <Ionicons
                    name={permissions?.batteryOptimization ? "checkmark-circle" : "battery-charging-outline"}
                    size={24}
                    color={permissions?.batteryOptimization ? '#10B981' : '#EF4444'}
                  />
                </View>
                <View style={styles.permissionText}>
                  <Text style={styles.permissionTitle}>
                    {language === 'tr' ? 'Pil Optimizasyonu' : 'Battery Optimization'}
                  </Text>
                  <Text style={styles.permissionDescription}>
                    {language === 'tr'
                      ? 'Arka planda alarm calmasi icin KRITIK (kapali olmali)'
                      : 'CRITICAL for background alarms (must be disabled)'}
                  </Text>
                </View>
              </View>
              {!permissions?.batteryOptimization && (
                <TouchableOpacity
                  style={styles.permissionButton}
                  onPress={handleRequestBatteryOptimization}
                >
                  <Text style={styles.permissionButtonText}>
                    {language === 'tr' ? 'Ayarla' : 'Set'}
                  </Text>
                </TouchableOpacity>
              )}
              {permissions?.batteryOptimization && (
                <Ionicons name="checkmark-circle" size={24} color="#10B981" />
              )}
            </View>
          )}

          {/* Cihaza Ozel Ayarlar (Xiaomi, Samsung, Huawei vb.) */}
          {Platform.OS === 'android' && permissions?.powerManagerRestricted && (
            <View style={styles.permissionItem}>
              <View style={styles.permissionInfo}>
                <View style={[styles.permissionIcon, { backgroundColor: '#F59E0B20' }]}>
                  <Ionicons
                    name="phone-portrait-outline"
                    size={24}
                    color="#F59E0B"
                  />
                </View>
                <View style={styles.permissionText}>
                  <Text style={styles.permissionTitle}>
                    {language === 'tr'
                      ? `${permissions.manufacturer || 'Cihaz'} Ozel Ayarlar`
                      : `${permissions.manufacturer || 'Device'} Settings`}
                  </Text>
                  <Text style={styles.permissionDescription}>
                    {language === 'tr'
                      ? 'Oto-baslatma veya arka plan izni (alarm icin onerilen)'
                      : 'Auto-start or background permission (recommended for alarms)'}
                  </Text>
                </View>
              </View>
              <TouchableOpacity
                style={[styles.permissionButton, styles.optionalButton]}
                onPress={handleOpenPowerManagerSettings}
              >
                <Text style={[styles.permissionButtonText, { color: colors.primary }]}>
                  {language === 'tr' ? 'Ayarla' : 'Set'}
                </Text>
              </TouchableOpacity>
            </View>
          )}

          {/* Bildirim Kanalı Ayarları */}
          <View style={styles.permissionItem}>
            <View style={styles.permissionInfo}>
              <View style={[styles.permissionIcon, { backgroundColor: '#3B82F620' }]}>
                <Ionicons name="settings-outline" size={24} color="#3B82F6" />
              </View>
              <View style={styles.permissionText}>
                <Text style={styles.permissionTitle}>
                  {language === 'tr' ? 'Bildirim Ayarları' : 'Notification Settings'}
                </Text>
                <Text style={styles.permissionDescription}>
                  {language === 'tr' 
                    ? 'Sessiz modda bile ses çalması için "İlaç Alarmları" kanalını kontrol edin' 
                    : 'Check "Medicine Alarms" channel to play sound even in silent mode'}
                </Text>
              </View>
            </View>
            <TouchableOpacity 
              style={[styles.permissionButton, styles.optionalButton]}
              onPress={handleOpenNotificationSettings}
            >
              <Text style={[styles.permissionButtonText, { color: colors.primary }]}>
                {language === 'tr' ? 'Aç' : 'Open'}
              </Text>
            </TouchableOpacity>
          </View>
        </View>

        {/* Info Box */}
        <View style={styles.infoBox}>
          <Ionicons name="information-circle" size={20} color={colors.primary} />
          <Text style={styles.infoText}>
            {language === 'tr' 
              ? 'Bu izinler sadece ilaç hatırlatmaları için kullanılır. Verileriniz güvende.'
              : 'These permissions are only used for medication reminders. Your data is safe.'}
          </Text>
        </View>

        {/* Continue Button */}
        <TouchableOpacity 
          style={[
            styles.continueButton,
            !allPermissionsGranted && styles.continueButtonDisabled
          ]}
          onPress={onComplete}
          disabled={!allPermissionsGranted}
        >
          <Text style={styles.continueButtonText}>
            {allPermissionsGranted 
              ? (language === 'tr' ? 'Devam Et' : 'Continue')
              : (language === 'tr' ? 'Lütfen izinleri verin' : 'Please grant permissions')}
          </Text>
          <Ionicons name="arrow-forward" size={20} color="#FFFFFF" />
        </TouchableOpacity>

        {/* Skip Option */}
        <TouchableOpacity style={styles.skipButton} onPress={onComplete}>
          <Text style={styles.skipButtonText}>
            {language === 'tr' ? 'Şimdilik Atla' : 'Skip for now'}
          </Text>
        </TouchableOpacity>
      </ScrollView>
    </SafeAreaView>
  );
}

