import React, { useState, useCallback, useRef, useEffect } from 'react';
import { View, ScrollView, Platform, UIManager } from 'react-native';
import { SafeAreaView } from 'react-native-safe-area-context';
import AsyncStorage from '@react-native-async-storage/async-storage';
import {
  PremiumCard,
  DailyScheduleSection,
  AppearanceSection,
  NotificationSection,
  DevTestSection,
  QuietHoursSection,
  AdditionalFeaturesSection,
  AccountSection,
  AboutSection,
  createSettingsStyles,
} from '../components/settings';
import { useSettingsScreen } from '../hooks/useSettingsScreen';
import { useLanguage } from '../contexts/LanguageContext';
import { useAlert } from '../contexts/AlertContext';

if (Platform.OS === 'android' && UIManager.setLayoutAnimationEnabledExperimental) {
  UIManager.setLayoutAnimationEnabledExperimental(true);
}

const DEV_MODE_TAP_COUNT = 5;
const DEV_MODE_TAP_TIMEOUT = 3000;

export default function SettingsScreen() {
  const {
    navigation,
    colors,
    isDark,
    theme,
    setTheme,
    language,
    setLanguage,
    settings,
    updateSettings,
    isSyncing,
    user,
    isPremium,
    remainingDays,
    pickerState,
    togglePicker,
    closePicker,
    parseTimeToDate,
    handleTimeChange,
    handleTestNotification,
    handleTestVoice,
    handleTestFullScreenAlarm,
    handleScheduleTestAlarm,
    handleAddTestMedicine,
    handleAddTestMedicine10s,
    handleDeleteTestMedicines,
    handleShowScheduledNotifications,
    handleClearAllData,
    handleSync,
    handleLogout,
    formatLastSync,
    formatTimeDisplay,
    getThemeLabel,
    getLanguageLabel,
  } = useSettingsScreen();

  const { t } = useLanguage();
  const { showInfo } = useAlert();
  const [isDevMode, setIsDevMode] = useState(false);
  const tapCountRef = useRef(0);
  const lastTapTimeRef = useRef(0);

  // Dev mode durumunu AsyncStorage'dan oku (kalıcı)
  useEffect(() => {
    AsyncStorage.getItem('dev-mode')
      .then(val => {
        if (val === 'true') setIsDevMode(true);
      })
      .catch(() => {});
  }, []);

  const handleVersionPress = useCallback(() => {
    const now = Date.now();

    if (now - lastTapTimeRef.current > DEV_MODE_TAP_TIMEOUT) {
      tapCountRef.current = 0;
    }

    lastTapTimeRef.current = now;
    tapCountRef.current += 1;

    if (tapCountRef.current >= DEV_MODE_TAP_COUNT) {
      tapCountRef.current = 0;
      const newDevMode = !isDevMode;
      setIsDevMode(newDevMode);
      AsyncStorage.setItem('dev-mode', newDevMode ? 'true' : 'false').catch(() => {});

      showInfo(
        newDevMode
          ? language === 'tr'
            ? 'Geliştirici Modu Açık'
            : 'Developer Mode Enabled'
          : language === 'tr'
            ? 'Geliştirici Modu Kapalı'
            : 'Developer Mode Disabled',
        newDevMode
          ? language === 'tr'
            ? 'Geliştirici test seçenekleri artık görünür.'
            : 'Developer test options are now visible.'
          : language === 'tr'
            ? 'Geliştirici test seçenekleri gizlendi.'
            : 'Developer test options are now hidden.'
      );
    }
  }, [isDevMode, language, showInfo]);

  const styles = createSettingsStyles(colors, isDark);

  return (
    <SafeAreaView style={styles.container} edges={['bottom']}>
      <ScrollView style={styles.scrollView}>
        <PremiumCard
          isPremium={isPremium}
          remainingDays={remainingDays}
          onPress={() => navigation.navigate('Premium')}
        />

        <DailyScheduleSection
          wakeUpTime={settings.wakeUpTime}
          sleepTime={settings.sleepTime}
          showWakeUpPicker={pickerState.showWakeUpPicker}
          showSleepPicker={pickerState.showSleepPicker}
          onWakeUpPress={() => togglePicker('showWakeUpPicker')}
          onSleepPress={() => togglePicker('showSleepPicker')}
          onWakeUpChange={handleTimeChange('wakeUpTime')}
          onSleepChange={handleTimeChange('sleepTime')}
          parseTimeToDate={parseTimeToDate}
          formatTimeDisplay={formatTimeDisplay}
        />

        <AppearanceSection
          showThemePicker={pickerState.showThemePicker}
          showLanguagePicker={pickerState.showLanguagePicker}
          onThemePress={() => togglePicker('showThemePicker')}
          onLanguagePress={() => togglePicker('showLanguagePicker')}
          onThemeSelect={themeValue => {
            setTheme(themeValue);
            closePicker('showThemePicker');
          }}
          onLanguageSelect={lang => {
            setLanguage(lang);
            closePicker('showLanguagePicker');
          }}
          getThemeLabel={getThemeLabel}
          getLanguageLabel={getLanguageLabel}
        />

        <NotificationSection
          settings={settings}
          showSnoozePicker={pickerState.showSnoozePicker}
          showSnoozeCountPicker={pickerState.showSnoozeCountPicker}
          showVolumePicker={pickerState.showVolumePicker}
          showConflictIntervalPicker={pickerState.showConflictIntervalPicker}
          onSettingChange={updateSettings}
          onSnoozePress={() => togglePicker('showSnoozePicker')}
          onSnoozeCountPress={() => togglePicker('showSnoozeCountPicker')}
          onVolumePress={() => togglePicker('showVolumePicker')}
          onConflictIntervalPress={() => togglePicker('showConflictIntervalPicker')}
          onTestNotification={handleTestNotification}
          onTestFullScreenAlarm={handleTestFullScreenAlarm}
          onTestVoice={handleTestVoice}
        />

        {isDevMode && (
          <DevTestSection
            onScheduleAlarm={handleScheduleTestAlarm}
            onAddTestMedicine={handleAddTestMedicine}
            onAddTestMedicine10s={handleAddTestMedicine10s}
            onDeleteTestMedicines={handleDeleteTestMedicines}
            onShowScheduledNotifications={handleShowScheduledNotifications}
            onClearAllData={handleClearAllData}
          />
        )}

        <QuietHoursSection
          settings={settings}
          showQuietStartPicker={pickerState.showQuietStartPicker}
          showQuietEndPicker={pickerState.showQuietEndPicker}
          onSettingChange={updateSettings}
          onQuietStartPress={() => togglePicker('showQuietStartPicker')}
          onQuietEndPress={() => togglePicker('showQuietEndPicker')}
          onQuietStartChange={handleTimeChange('quietHoursStart')}
          onQuietEndChange={handleTimeChange('quietHoursEnd')}
          parseTimeToDate={parseTimeToDate}
          formatTimeDisplay={formatTimeDisplay}
        />

        <AdditionalFeaturesSection
          onInteractionsPress={() => navigation.navigate('Interactions')}
          onSecurityPress={() => navigation.navigate('Security')}
          onTtsPress={() => navigation.navigate('TtsSettings')}
          ttsEnabled={settings.ttsEnabled}
        />

        <AccountSection
          userEmail={user?.email}
          lastSyncFormatted={formatLastSync()}
          isSyncing={isSyncing}
          onSyncPress={handleSync}
          onLogoutPress={handleLogout}
        />

        <AboutSection onVersionPress={handleVersionPress} isDevMode={isDevMode} />

        <View style={{ height: 40 }} />
      </ScrollView>
    </SafeAreaView>
  );
}

import { AIConfig, AIProvider, AISearchResult, GlobalMedicine, MedicineForm, MedicineProspectus } from '../types';
import { doc, getDoc } from 'firebase/firestore';
import { db } from '../config/firebase';
import { createScopedLogger } from '../utils/logger';

const log = createScopedLogger('AIMedicineService');

// ============ AI YAPILANDIRMA YÖNETİMİ ============

// Firebase'den AI yapılandırmasını al
const AI_CONFIG_DOC = 'config/ai';

interface StoredAIConfig {
  provider: AIProvider;
  geminiApiKey: string;
  openaiApiKey: string;
  geminiModel: string;
  openaiModel: string;
}

/**
 * Firebase'den AI yapılandırmasını getir
 */
export async function getAIConfig(): Promise<AIConfig | null> {
  try {
    const configRef = doc(db, 'config', 'ai');
    const snapshot = await getDoc(configRef);

    if (!snapshot.exists()) {
      log.debug('AI yapilandirmasi bulunamadi');
      return null;
    }

    const data = snapshot.data() as StoredAIConfig;
    return {
      provider: data.provider || 'gemini',
      geminiApiKey: data.geminiApiKey,
      openaiApiKey: data.openaiApiKey,
      model: data.provider === 'gemini' ? data.geminiModel : data.openaiModel,
    };
  } catch (error) {
    log.error('AI yapilandirma getirme hatasi', error);
    return null;
  }
}

// ============ BARKOD İLE İLAÇ ARAMA ============

/**
 * Barkod ile web'te arama yapıp AI ile ilaç bilgilerini çıkar
 */
export async function searchMedicineByBarcodeAI(barcode: string): Promise<AISearchResult> {
  try {
    const config = await getAIConfig();
    
    if (!config) {
      return {
        success: false,
        confidence: 0,
        error: 'AI yapılandırması bulunamadı. Admin panelinden API key girilmeli.',
      };
    }

    // Provider'a göre arama yap
    if (config.provider === 'gemini' && config.geminiApiKey) {
      return await searchWithGemini(barcode, config.geminiApiKey, config.model);
    } else if (config.provider === 'openai' && config.openaiApiKey) {
      return await searchWithOpenAI(barcode, config.openaiApiKey, config.model);
    }

    return {
      success: false,
      confidence: 0,
      error: 'Geçerli bir AI API key bulunamadı.',
    };
  } catch (error: unknown) {
    log.error('AI arama hatasi', error);
    const errorMessage = error instanceof Error ? error.message : 'AI araması başarısız oldu.';
    return {
      success: false,
      confidence: 0,
      error: errorMessage,
    };
  }
}

// ============ GEMİNİ İLE ARAMA ============

async function searchWithGemini(
  barcode: string,
  apiKey: string,
  model: string = 'gemini-2.5-flash'
): Promise<AISearchResult> {
  const prompt = createSearchPrompt(barcode);

  try {
    const response = await fetch(
      `https://generativelanguage.googleapis.com/v1beta/models/${model}:generateContent?key=${apiKey}`,
      {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({
          contents: [
            {
              parts: [{ text: prompt }],
            },
          ],
          generationConfig: {
            temperature: 0.1,
            maxOutputTokens: 2048,
          },
        }),
      }
    );

    if (!response.ok) {
      const errorData = await response.json();
      throw new Error(errorData.error?.message || 'Gemini API hatası');
    }

    const data = await response.json();
    const textResponse = data.candidates?.[0]?.content?.parts?.[0]?.text;

    if (!textResponse) {
      return {
        success: false,
        confidence: 0,
        error: 'AI yanıt vermedi.',
      };
    }

    return parseAIResponse(textResponse, barcode, 'Gemini');
  } catch (error: unknown) {
    log.error('Gemini arama hatasi', error);
    const errorMessage = error instanceof Error ? error.message : 'Gemini araması başarısız.';
    return {
      success: false,
      confidence: 0,
      error: errorMessage,
    };
  }
}

// ============ OPENAİ İLE ARAMA ============

async function searchWithOpenAI(
  barcode: string,
  apiKey: string,
  model: string = 'gpt-4o-mini'
): Promise<AISearchResult> {
  const prompt = createSearchPrompt(barcode);

  try {
    const response = await fetch('https://api.openai.com/v1/chat/completions', {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        Authorization: `Bearer ${apiKey}`,
      },
      body: JSON.stringify({
        model,
        messages: [
          {
            role: 'system',
            content: 'Sen bir ilaç veritabanı asistanısın. Barkod numaralarına göre ilaç bilgilerini JSON formatında döndürürsün.',
          },
          {
            role: 'user',
            content: prompt,
          },
        ],
        temperature: 0.1,
        max_tokens: 2048,
      }),
    });

    if (!response.ok) {
      const errorData = await response.json();
      throw new Error(errorData.error?.message || 'OpenAI API hatası');
    }

    const data = await response.json();
    const textResponse = data.choices?.[0]?.message?.content;

    if (!textResponse) {
      return {
        success: false,
        confidence: 0,
        error: 'AI yanıt vermedi.',
      };
    }

    return parseAIResponse(textResponse, barcode, 'OpenAI');
  } catch (error: unknown) {
    log.error('OpenAI arama hatasi', error);
    const errorMessage = error instanceof Error ? error.message : 'OpenAI araması başarısız.';
    return {
      success: false,
      confidence: 0,
      error: errorMessage,
    };
  }
}

