/**
 * Timeout wrapper fonksiyonu - memory leak'i önler
 */
const withTimeout = <T>(
  promise: Promise<T>,
  timeoutMs: number,
  errorMessage: string
): Promise<T> => {
  let timer: ReturnType<typeof setTimeout> | null = null;

  return Promise.race([
    promise.finally(() => {
      if (timer) {
        clearTimeout(timer);
        timer = null;
      }
    }),
    new Promise<T>((_, reject) => {
      timer = setTimeout(() => reject(new Error(errorMessage)), timeoutMs);
    }),
  ]);
};

// Tüm verileri buluta yükle
export async function uploadAllDataToCloud(userId: string, data: SyncData): Promise<void> {
  log.debug('Veriler buluta yükleniyor');

  try {
    await withTimeout(
      Promise.all([
        syncMedicinesToCloud(userId, data.medicines),
        syncReminderTimesToCloud(userId, data.reminderTimes),
        syncMedicineLogsToCloud(userId, data.medicineLogs),
        syncSettingsToCloud(userId, data.settings),
      ]),
      30000, // 30 saniye timeout
      'Senkronizasyon zaman aşımına uğradı. İnternet bağlantınızı kontrol edin.'
    );

    log.debug('Veriler buluta yüklendi');
  } catch (error: unknown) {
    log.error('Buluta yükleme hatası', error);
    // Offline hatası için özel mesaj
    const errorObj = error as { code?: string; message?: string };
    if (errorObj.code === 'unavailable' || errorObj.message?.includes('offline')) {
      throw new Error('İnternet bağlantısı yok. Lütfen bağlantınızı kontrol edin.');
    }
    throw error;
  }
}

// Tüm verileri buluttan indir
export async function downloadAllDataFromCloud(userId: string): Promise<SyncData | null> {
  log.debug('Veriler buluttan indiriliyor');

  try {
    const [medicines, reminderTimes, medicineLogs, settings] = await withTimeout(
      Promise.all([
        getMedicinesFromCloud(userId),
        getReminderTimesFromCloud(userId),
        getMedicineLogsFromCloud(userId),
        getSettingsFromCloud(userId),
      ]),
      30000, // 30 saniye timeout
      'Veri indirme zaman aşımına uğradı. İnternet bağlantınızı kontrol edin.'
    );

    // Eğer hiç veri yoksa null döndür
    if (medicines.length === 0 && !settings) {
      log.debug('Bulutta veri bulunamadı');
      return null;
    }

    log.debug('Veriler buluttan indirildi');

    return {
      medicines,
      reminderTimes,
      medicineLogs,
      settings: settings || DEFAULT_SETTINGS,
    };
  } catch (error: unknown) {
    log.error('Buluttan veri indirme hatası', error);
    // Offline hatası için özel mesaj
    const errorObj = error as { code?: string; message?: string };
    if (errorObj.code === 'unavailable' || errorObj.message?.includes('offline')) {
      throw new Error('İnternet bağlantısı yok. Lütfen bağlantınızı kontrol edin.');
    }
    throw error;
  }
}

/**
 * Kullanıcı verilerini tamamen sil
 * 500'lük batch limitine dikkat ederek
 */
export async function deleteAllUserData(userId: string): Promise<void> {
  // İlaçları sil
  const medicines = await getDocs(getMedicinesRef(userId));
  await deleteDocumentsInBatches(medicines.docs);

  // Zamanları sil
  const times = await getDocs(getReminderTimesRef(userId));
  await deleteDocumentsInBatches(times.docs);

  // Logları sil
  const logs = await getDocs(getMedicineLogsRef(userId));
  await deleteDocumentsInBatches(logs.docs);

  // Ayarları sil
  await deleteDoc(getSettingsDocRef(userId));
}

/**
 * Dokümanları batch limitine göre gruplar halinde sil
 */
async function deleteDocumentsInBatches(docs: QueryDocumentSnapshot[]): Promise<void> {
  for (let i = 0; i < docs.length; i += FIRESTORE_BATCH_LIMIT) {
    const batch = writeBatch(db);
    const chunk = docs.slice(i, i + FIRESTORE_BATCH_LIMIT);

    chunk.forEach(docSnapshot => {
      batch.delete(docSnapshot.ref);
    });

    await batch.commit();
    log.debug(`${chunk.length} doküman silindi`);
  }
}

/**
 * Turkish Medicine Service
 *
 * Hibrit ilaç arama servisi:
 * 1. Open Food Facts API - Ücretsiz, açık kaynak barkod veritabanı
 * 2. TİTCK Excel cache - Türkiye resmi ilaç listesi (offline)
 * 3. İlacabak.com web scraping (ilaç adı araması için)
 */

import AsyncStorage from '@react-native-async-storage/async-storage';
import { GlobalMedicine, MedicineForm } from '../types';
import { createScopedLogger } from '../utils/logger';

const log = createScopedLogger('TurkishMedicineService');

// ============ OPEN FOOD FACTS API ============

interface OpenFoodFactsProduct {
  code: string;
  product_name?: string;
  product_name_tr?: string;
  brands?: string;
  categories?: string;
  ingredients_text?: string;
  quantity?: string;
  image_url?: string;
  countries?: string;
}

interface OpenFoodFactsResponse {
  status: number;
  status_verbose: string;
  code: string;
  product?: OpenFoodFactsProduct;
}

/**
 * Open Food Facts API ile barkod ara
 * Not: Ağırlıklı olarak gıda ürünleri için, ilaçlar sınırlı olabilir
 */
export async function searchOpenFoodFacts(
  barcode: string
): Promise<Partial<GlobalMedicine> | null> {
  try {
    log.debug('OpenFoodFacts aranıyor', { barcode });

    const response = await fetch(`https://world.openfoodfacts.org/api/v0/product/${barcode}.json`, {
      method: 'GET',
      headers: {
        'User-Agent': 'IlacHatirlatici/1.0 (Android)',
      },
    });

    if (!response.ok) {
      log.debug('OpenFoodFacts API hatası', { status: response.status });
      return null;
    }

    const data: OpenFoodFactsResponse = await response.json();

    if (data.status !== 1 || !data.product) {
      log.debug('OpenFoodFacts ürün bulunamadı');
      return null;
    }

    const product = data.product;
    log.debug('OpenFoodFacts bulundu', { name: product.product_name || product.product_name_tr });

    // İlaç olup olmadığını kontrol et
    const categories = (product.categories || '').toLowerCase();
    const isMedicine =
      categories.includes('medicine') ||
      categories.includes('pharmaceutical') ||
      categories.includes('ilaç') ||
      categories.includes('drug');

    const rawName = product.product_name_tr || product.product_name || 'Bilinmeyen Ürün';
    return {
      barcode: barcode,
      name: fixTurkishCharacters(rawName),
      manufacturer: product.brands || 'Bilinmiyor',
      dosage: fixTurkishCharacters(product.quantity || ''),
      form: detectMedicineForm(rawName),
      country: detectCountry(product.countries),
      imageUrl: product.image_url,
    };
  } catch (error) {
    log.error('OpenFoodFacts hata', error);
    return null;
  }
}

// ============ TİTCK EXCEL CACHE ============

const TITCK_CACHE_KEY = '@titck_medicine_cache';
const TITCK_CACHE_TIMESTAMP_KEY = '@titck_cache_timestamp';
const CACHE_EXPIRY_DAYS = 7;

interface TITCKMedicine {
  barcode: string;
  name: string;
  manufacturer: string;
  price: number;
  atcCode?: string;
  dosage?: string;
}

/**
 * TİTCK cache'den barkod ara
 */
export async function searchTITCKCache(barcode: string): Promise<Partial<GlobalMedicine> | null> {
  try {
    log.debug('TITCK Cache aranıyor', { barcode });

    const cacheData = await AsyncStorage.getItem(TITCK_CACHE_KEY);
    if (!cacheData) {
      log.debug('TITCK Cache boş');
      return null;
    }

    const medicines: TITCKMedicine[] = JSON.parse(cacheData);
    const found = medicines.find(m => m.barcode === barcode);

    if (!found) {
      log.debug('TITCK Cache bulunamadı');
      return null;
    }

    log.debug('TITCK Cache bulundu', { name: found.name });

    const fixedName = fixTurkishCharacters(found.name);
    return {
      barcode: found.barcode,
      name: fixedName,
      manufacturer: found.manufacturer,
      dosage: fixTurkishCharacters(found.dosage || extractDosageFromName(found.name)),
      form: detectMedicineForm(found.name),
      country: 'TR',
    };
  } catch (error) {
    log.error('TITCK Cache hata', error);
    return null;
  }
}

/**
 * TİTCK verilerini cache'e kaydet
 * Not: Bu fonksiyon admin panelinden veya manuel olarak çağrılabilir
 */
export async function updateTITCKCache(medicines: TITCKMedicine[]): Promise<void> {
  try {
    await AsyncStorage.setItem(TITCK_CACHE_KEY, JSON.stringify(medicines));
    await AsyncStorage.setItem(TITCK_CACHE_TIMESTAMP_KEY, Date.now().toString());
    log.debug('TITCK Cache güncellendi', { count: medicines.length });
  } catch (error) {
    log.error('TITCK Cache güncelleme hatası', error);
    throw error;
  }
}

/**
 * Cache'in güncel olup olmadığını kontrol et
 */
export async function isTITCKCacheValid(): Promise<boolean> {
  try {
    const timestamp = await AsyncStorage.getItem(TITCK_CACHE_TIMESTAMP_KEY);
    if (!timestamp) return false;

    const cacheAge = Date.now() - parseInt(timestamp);
    const maxAge = CACHE_EXPIRY_DAYS * 24 * 60 * 60 * 1000;

    return cacheAge < maxAge;
  } catch {
    return false;
  }
}

/**
 * Cache'deki ilaç sayısını getir
 */
export async function getTITCKCacheCount(): Promise<number> {
  try {
    const cacheData = await AsyncStorage.getItem(TITCK_CACHE_KEY);
    if (!cacheData) return 0;

    const medicines: TITCKMedicine[] = JSON.parse(cacheData);
    return medicines.length;
  } catch {
    return 0;
  }
}

